/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A53 staging source: frozen manifest inchoate–Indian; audit and publish every 20 lemmas. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Claims are limited to the stated formation; uncertain history is left open.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});
D('inchoate',{etymology:E('Inchoate comes from Latin inchoatus, “begun,” from inchoare, “to begin.” It describes something in an early stage that remains vague or incomplete.','inchoate'),contexts:[C('inchoate.s1','项目规划','The committee had only an inchoate proposal, with no clear budget, timeline, or assigned responsibilities.','委员会只有一份初步而不成形的提案，没有明确预算、时间表或分工。','The committee had only an inchoate proposal / with no clear budget / timeline / or assigned responsibilities.','inchoate 表示刚开始发展、仍然模糊或不完整的。','提案尚缺预算和执行细节，处于早期阶段。')],mistakes:[M('The committee called the fully costed, scheduled, and approved plan inchoate.','The committee called the vague early draft inchoate.','内容完整并已批准的计划不再是初步不成形的。')],quiz:[Q('inchoate',1,1,'An inchoate plan is?','at an early, vague, or incomplete stage','fully detailed and finished','impossible to read','at an early, vague, or incomplete stage','inchoate 表示初步而未成形的。'),Q('inchoate',2,1,'Which proposal is inchoate?','a rough idea with no budget or schedule','a final plan approved and funded','a report with every step documented','a rough idea with no budget or schedule','缺少计划细节的粗略构想还不成熟。'),Q('inchoate',3,1,'Inchoate is closest to?','incipient and undeveloped','immaculate and flawless','impartial and fair','incipient and undeveloped','incipient 与 inchoate 都可指初期状态。'),Q('inchoate',4,1,'An inchoate discussion may still need?','a clearer shape and more detail','no further development','a legal hearing','a clearer shape and more detail','初步讨论尚需明确内容并继续发展。')]});
D('inchworm',{etymology:E('Inchworm is named for the looping way a geometer moth larva moves, as if measuring forward in inches. It is the larva of a geometer moth.','inchworm'),contexts:[C('inchworm.s1','花园观察','The child spotted an inchworm arching its body between two leaves before it stretched forward again.','孩子看到一只尺蠖在两片叶子之间弓起身体，然后再次向前伸展。','The child spotted an inchworm / arching its body between two leaves / before it stretched forward again.','inchworm 指尺蛾的幼虫，移动时身体呈环状弯曲。','幼虫先弓身再伸展前进，呈现其典型步态。')],mistakes:[M('The guide identified the flying adult butterfly as an inchworm, although it had no larval body or looping gait.','The guide identified the looping caterpillar as an inchworm.','inchworm 指尺蛾幼虫，不是已经羽化的成虫。')],quiz:[Q('inchworm',1,1,'An inchworm is the larva of a?','geometer moth','horsefly','hornbill','geometer moth','inchworm 是尺蛾幼虫。'),Q('inchworm',2,1,'Why is it called an inchworm?','it moves by looping its body forward','it measures exactly one inch','it lives only inside rulers','it moves by looping its body forward','它弓起再伸展的动作像逐寸测量。'),Q('inchworm',3,1,'Which movement fits an inchworm?','arching and stretching between leaves','flying on broad wings','swimming with fins','arching and stretching between leaves','尺蠖常弓身并伸展前进。'),Q('inchworm',4,1,'An inchworm is a kind of?','moth caterpillar','adult bird','small mammal','moth caterpillar','它是蛾类幼虫。')]});
D('incidence',{etymology:E('Incidence comes from Latin incidentia, from incidere, “to fall upon or happen.” It can mean how often something occurs, the fact of its occurring, or the extent to which it affects a population.','incidence'),contexts:[C('incidence.s1','公共卫生','The report found that the incidence of seasonal flu fell after the vaccination campaign began.','报告发现，疫苗接种活动开始后，季节性流感的发生率下降了。','The report found / that the incidence of seasonal flu fell / after the vaccination campaign / began.','incidence 在此指某疾病或事件发生的频率。','报告比较活动前后的流感发生率。')],mistakes:[M('The survey said the incidence of new cases fell while the number of newly recorded cases rose sharply.','The survey said the incidence of new cases rose when more new cases were recorded.','新增病例大幅增加与发生率下降的说法矛盾。')],quiz:[Q('incidence',1,1,'The incidence of a disease describes?','how often it occurs','how severe one single case is only','how clearly a chart is drawn','how often it occurs','incidence 可表示疾病发生频率。'),Q('incidence',2,2,'“The incident of flooding was recorded” uses incident to mean?','the fact that flooding happened','a patient’s recovery rate','a person’s preference','the fact that flooding happened','s2 指事情发生这一事实。'),Q('incidence',3,3,'The incidence of an illness among residents may measure?','the extent to which people are affected','the color of the clinic','the time needed to read a chart','the extent to which people are affected','s3 指事件影响人群的范围或程度。'),Q('incidence',4,1,'Researchers track incidence to learn whether cases are?','becoming more or less frequent','more colorful','easier to pronounce','becoming more or less frequent','发生率数据可显示病例是否增多或减少。')]});
D('incident',{etymology:E('Incident comes from Latin incidens, “happening,” from incidere, “to fall upon.” It can mean an event, a minor episode, a hostile event between groups, or something naturally connected with another matter.','incident'),contexts:[C('incident.s1','社区安全','The school reviewed the incident in which a delivery van struck the gate and damaged the entry sensor.','学校复查了一起事件：一辆送货车撞上大门并损坏了入口传感器。','The school reviewed the incident / in which a delivery van struck the gate / and damaged / the entry sensor.','incident 在此指发生的一件事，通常带有不愉快或意外性质。','车辆撞门并损坏设备构成需要复查的事件。')],mistakes:[M('The report described the crash as an incident but claimed that no event had taken place.','The report described the crash as an incident because it was an event that required review.','incident 本身指发生的事情，不能说没有任何事件。')],quiz:[Q('incident',1,1,'An incident is often?','an event, especially an unpleasant one','a type of household income','a disease-resistant state','an event, especially an unpleasant one','incident 常指意外或不愉快事件。'),Q('incident',2,2,'A brief minor episode can be called an?','incident','incinerator','inclination','incident','s2 指较小事件或插曲。'),Q('incident',3,3,'A hostile clash between groups is an?','incident','illustration','inclusion','incident','s3 可指群体或国家间的敌对事件。'),Q('incident',4,4,'Some delays are incident to large projects means they are?','naturally connected with them','unrelated to them','impossible to notice','naturally connected with them','s4 表示自然伴随某事发生。')]});
D('incidental',{etymology:E('Incidental comes from incident, ultimately from Latin incidere, “to happen.” It means less important or occurring as a by-product rather than being the main purpose.','incidental'),contexts:[C('incidental.s1','差旅报销','The travel grant covers incidental expenses such as local bus fares, but not the conference registration fee.','差旅补助涵盖当地公交车费等零星开支，但不包括会议注册费。','The travel grant covers incidental expenses / such as local bus fares / but not / the conference registration fee.','incidental 表示附带的、次要的或非主要目的的。','公交小额开支属于出行中的附带费用。')],mistakes:[M('The report called the main objective incidental and treated a tiny printing cost as the project’s central purpose.','The report called the small printing cost incidental to the project’s main objective.','主要目标不是次要附带事项。')],quiz:[Q('incidental',1,1,'An incidental expense is?','a small additional cost','the main purpose of a project','a legal accusation','a small additional cost','incidental 可指附带的小额费用。'),Q('incidental',2,1,'An incidental detail is?','less important than the main point','the only central issue','impossible to understand','less important than the main point','该词也表示次要的。'),Q('incidental',3,1,'Which cost is incidental to a conference trip?','a local bus fare','the principal research question','the conference itself','a local bus fare','当地交通费是旅程中的附带支出。'),Q('incidental',4,1,'Incidental is closest to?','secondary','essential','immaculate','secondary','secondary 表示次要的，与 incidental 相近。')]});
D('incidentally',{etymology:E('Incidentally is formed from incidental plus -ly. It introduces an extra remark, or describes something that happens without being planned.','incidentally'),contexts:[C('incidentally.s1','日常交谈','Incidentally, the library has extended its weekend hours, so we can return the books on Sunday.','顺便说一句，图书馆延长了周末开放时间，所以我们可以星期天还书。','Incidentally / the library has extended its weekend hours / so we can return the books / on Sunday.','incidentally 在此用于引出补充说明。','说话者插入一条相关但额外的信息。')],mistakes:[M('The speaker used incidentally to present the only main conclusion of the meeting and nothing additional.','The speaker used incidentally to add a side remark about the library hours.','incidentally 通常引出附带说明，而非唯一主结论。')],quiz:[Q('incidentally',1,1,'At the start of a sentence, incidentally can mean?','by the way','at the exact same time','as the main conclusion','by the way','incidentally 常用于引入补充信息。'),Q('incidentally',2,2,'An event that happens incidentally is?','unplanned or not intended','carefully scheduled as the main aim','impossible to happen','unplanned or not intended','s2 表示非计划地发生。'),Q('incidentally',3,1,'Which sentence uses incidentally as a side remark?','Incidentally, the café closes early today.','The incidentally caused the door to close.','She incidentally a new schedule yesterday.','Incidentally, the café closes early today.','句首 incidentally 表示“顺便说一下”。'),Q('incidentally',4,1,'Incidentally is related to which adjective?','incidental','incoherent','incipient','incidental','incidentally 由 incidental 加 -ly 构成。','word-formation')]});
D('incinerate',{etymology:E('Incinerate comes from Latin incinerare, “to reduce to ashes,” from in- and cinis, “ashes.” It means to destroy waste or a body completely by burning.','incinerate'),contexts:[C('incinerate.s1','废弃物管理','The facility will incinerate contaminated laboratory waste under controlled conditions and monitor the emissions.','该设施将在受控条件下焚烧受污染的实验室废弃物，并监测排放物。','The facility will incinerate contaminated laboratory waste / under controlled conditions / and monitor / the emissions.','incinerate 表示通过燃烧彻底销毁废弃物或遗体。','实验室废物在受控设备中焚烧处理。')],mistakes:[M('The facility incinerated the waste by storing it untreated in an open field without burning it.','The facility incinerated the waste in a controlled high-temperature unit.','未燃烧地露天存放不是 incinerate。')],quiz:[Q('incinerate',1,1,'To incinerate waste is to?','destroy it by burning it completely','recycle it without heat','include it in a report','destroy it by burning it completely','incinerate 表示焚烧销毁。'),Q('incinerate',2,1,'Which material might a facility incinerate?','contaminated waste under controlled procedures','a clean reusable glass bottle for ordinary use','a digital file on a screen','contaminated waste under controlled procedures','受污染废弃物可在规范设施中焚烧处理。'),Q('incinerate',3,1,'Incinerate is related to the Latin word for?','ashes','law','image','ashes','cinis 意为灰烬。','word-formation'),Q('incinerate',4,1,'Which sentence uses incinerate correctly?','The plant incinerates regulated waste safely.','The plant incinerates the report by reading it aloud.','The plant incinerated the cold by opening a window.','The plant incinerates regulated waste safely.','incinerate 的宾语通常是被焚烧销毁的材料。')]});
D('incineration',{etymology:E('Incineration is formed from incinerate plus -ion. It names the process of completely burning waste or a body.','incineration'),contexts:[C('incineration.s1','环境工程','The review compared incineration with other waste-treatment methods and included measurements of energy use and emissions.','评估比较了焚烧与其他废物处理方法，并纳入能源消耗和排放量的测量数据。','The review compared incineration / with other waste-treatment methods / and included measurements / of energy use and emissions.','incineration 指将废物或遗体彻底焚烧的过程。','报告把焚烧作为一种废物处理方式进行比较。')],mistakes:[M('The report defined incineration as burying untreated waste in a landfill without burning it.','The report defined incineration as treating material by complete burning.','不经燃烧而掩埋不是 incineration。')],quiz:[Q('incineration',1,1,'Incineration is the process of?','burning material completely','burying material without heat','sorting books alphabetically','burning material completely','incineration 指焚烧过程。'),Q('incineration',2,1,'An environmental review of incineration may measure?','energy use and emissions','the slope of a road','the size of a bookshelf','energy use and emissions','焚烧评估会关注能耗与排放。'),Q('incineration',3,1,'Incineration is the noun related to?','incinerate','incite','include','incinerate','incineration 是 incinerate 的名词形式。','word-formation'),Q('incineration',4,1,'Which method is incineration?','controlled burning of waste','washing and reusing a container','leaving waste in storage unchanged','controlled burning of waste','受控焚烧属于 incineration。')]});
D('incipient',{etymology:E('Incipient comes from Latin incipiens, “beginning,” from incipere, “to begin.” It describes something starting to appear or develop.','incipient'),contexts:[C('incipient.s1','设备维护','Technicians spotted incipient corrosion around the pipe joint and repaired the seal before the damage spread.','技术人员发现管道接头周围刚开始出现腐蚀，并在损坏扩散前修好了密封。','Technicians spotted incipient corrosion / around the pipe joint / and repaired the seal / before the damage spread.','incipient 表示刚开始显现或发展的。','腐蚀处于初期，及时处理可防止扩大。')],mistakes:[M('The engineer called the fully developed, long-standing rust incipient even though it had spread across the entire pipe.','The engineer called the first small signs of rust incipient corrosion.','已经大范围发展的腐蚀不再是刚出现的状态。')],quiz:[Q('incipient',1,1,'Incipient damage is?','just beginning to appear','fully developed over many years','impossible to observe','just beginning to appear','incipient 表示初现、刚开始发展的。'),Q('incipient',2,1,'Which is an incipient problem?','the first small crack in a new pipe','a pipe already broken into pieces','a completed repair','the first small crack in a new pipe','刚出现的小裂缝是问题的初期征兆。'),Q('incipient',3,1,'Incipient is close in meaning to?','beginning','inconclusive','incorruptible','beginning','incipient 源自表示开始的词。','word-formation'),Q('incipient',4,1,'Why notice incipient corrosion early?','it may be repaired before spreading','it has already destroyed every part','it cannot be seen at all','it may be repaired before spreading','早期发现有助于在腐蚀扩散前处理。')]});
D('incise',{etymology:E('Incise comes from Latin incidere, “to cut into,” formed from in- and caedere, “to cut.” It means cutting a line or pattern into a hard surface.','incise'),contexts:[C('incise.s1','工艺制作','The craftworker used a fine tool to incise a geometric pattern into the stone tile.','工匠用细工具在石砖上刻出几何图案。','The craftworker used a fine tool / to incise a geometric pattern / into the stone tile.','incise 表示在坚硬表面上刻出线条或图案。','图案被切刻在石砖表面。')],mistakes:[M('The artist incised the stone by painting a removable pattern on paper beside it.','The artist incised the stone by cutting the pattern directly into its surface.','只在旁边纸上作画没有切刻石面。')],quiz:[Q('incise',1,1,'To incise a design is to?','cut it into a hard surface','paint it on a distant wall','describe it aloud','cut it into a hard surface','incise 表示刻入表面。'),Q('incise',2,1,'Which material might an artist incise?','stone','moving air','a spoken conversation','stone','石头可被刻出线条或图案。'),Q('incise',3,1,'Incise is most closely related to?','cut','include','incline','cut','incise 与切刻有关。','word-formation'),Q('incise',4,1,'Which sentence uses incise correctly?','She incised initials into the wooden panel.','She incised the panel by thinking about it.','She incised the room by turning on a lamp.','She incised initials into the wooden panel.','把字母刻入木板符合 incise 的搭配。')]});
D('incisive',{etymology:E('Incisive comes from Latin incisivus, from incidere, “to cut into.” Figuratively, it describes a sharp mind or comment that gets directly to the point.','incisive'),contexts:[C('incisive.s1','编辑评议','The editor’s incisive question exposed the gap between the report’s headline claim and its actual evidence.','编辑提出的尖锐问题揭示了报告标题主张与实际证据之间的差距。','The editor’s incisive question / exposed the gap / between the report’s headline claim / and its actual evidence.','incisive 形容思维或评论敏锐、直指要点的。','问题准确指出主张与证据间的关键缺口。')],mistakes:[M('The reviewer called the vague comment incisive even though it never identified a point or clarified an issue.','The reviewer called the focused question incisive because it went straight to the central issue.','含糊不清且没有指出要点的评论不够 incisive。')],quiz:[Q('incisive',1,1,'An incisive comment is?','sharp and directly to the point','long but irrelevant','difficult to read','sharp and directly to the point','incisive 表示敏锐而切中要点。'),Q('incisive',2,1,'Which question is incisive?','one that identifies the report’s central evidence gap','one that repeats unrelated background','one that avoids the issue entirely','one that identifies the report’s central evidence gap','指出证据关键缺口的问题切中要点。'),Q('incisive',3,1,'Incisive derives from a word meaning?','to cut into','to welcome a guest','to burn to ashes','to cut into','incisive 的词源与“切入”有关，比喻切中要害。','word-formation'),Q('incisive',4,1,'An incisive analyst is likely to?','identify the key point clearly','miss every important connection','avoid forming any opinion','identify the key point clearly','敏锐的分析者能明确指出核心问题。')]});
D('incite',{etymology:E('Incite comes from Latin incitare, “to urge or set in motion,” formed from in- and citare, “to summon.” It means stirring someone toward strong, violent, or illegal action.','incite'),contexts:[C('incite.s1','媒体素养','The moderator removed the post because it appeared to incite violence rather than encourage peaceful discussion.','主持人删除了这则帖子，因为它似乎在煽动暴力，而不是鼓励和平讨论。','The moderator removed the post / because it appeared to incite violence / rather than encourage / peaceful discussion.','incite 表示煽动或激起强烈、暴力或违法行动。','帖子鼓动暴力，与和平讨论相反。')],mistakes:[M('The moderator said the post incited violence even though it explicitly urged readers to remain peaceful and avoid harm.','The moderator said the post promoted peaceful discussion rather than inciting violence.','明确劝人和平克制不属于煽动暴力。')],quiz:[Q('incite',1,1,'To incite a crowd is to?','stir it toward strong or violent action','calm it with clear peaceful guidance','teach it to read','stir it toward strong or violent action','incite 表示煽动、激起。'),Q('incite',2,1,'Which message could incite violence?','a call urging people to attack others','a request to leave peacefully','a neutral weather report','a call urging people to attack others','号召攻击他人可能煽动暴力。'),Q('incite',3,1,'Incite can also refer to urging?','illegal or intense action','only gentle relaxation','a period of one hour','illegal or intense action','该词也可指煽动违法或强烈行动。'),Q('incite',4,1,'The Latin source of incite meant roughly?','to urge or set in motion','to cut a line into stone','to receive a guest','to urge or set in motion','incitare 有催促、驱动之意。','word-formation')]});
D('inclement',{etymology:E('Inclement comes from Latin inclementia, “harshness,” formed from in- and clemens, “mild or gentle.” It describes unpleasantly cold, wet, or stormy weather.','inclement'),contexts:[C('inclement.s1','户外活动','The organizers postponed the coastal hike because inclement weather brought strong winds and driving rain.','强风和暴雨带来恶劣天气，组织者因此推迟了海岸徒步活动。','The organizers postponed the coastal hike / because inclement weather / brought strong winds / and driving rain.','inclement 形容寒冷、潮湿或暴风雨等恶劣天气。','强风与倾盆大雨使户外活动不适宜进行。')],mistakes:[M('The picnic continued during inclement weather with warm sunshine, calm air, and dry ground.','The picnic was postponed because inclement weather brought cold rain and strong wind.','温暖晴朗、无风干燥并非恶劣天气。')],quiz:[Q('inclement',1,1,'Inclement weather is often?','cold, wet, or stormy','warm, dry, and calm','impossible to predict exactly','cold, wet, or stormy','inclement 通常描述恶劣天气。'),Q('inclement',2,1,'Which forecast is inclement?','freezing rain with strong winds','mild sunshine and a light breeze','clear skies all day','freezing rain with strong winds','冻雨和强风属于恶劣天气。'),Q('inclement',3,1,'An event may be canceled due to?','inclement weather','a clear public image','an incidental note','inclement weather','恶劣天气可能导致活动取消。'),Q('inclement',4,1,'Inclement originally related to the idea of not being?','mild or gentle','large','readable','mild or gentle','词源由否定词缀和表示温和的词构成。','word-formation')]});
D('inclination',{etymology:E('Inclination comes from Latin inclinatio, from inclinare, “to bend or lean.” It can mean a feeling that makes someone want to act a certain way or a slope away from a level or upright line.','inclination'),contexts:[C('inclination.s1','职业选择','Maya has an inclination toward teaching, so she volunteers to explain difficult topics whenever the study group meets.','玛雅有从事教学的倾向，因此学习小组每次聚会时她都会主动解释难点。','Maya has an inclination toward teaching / so she volunteers / to explain difficult topics / whenever the study group meets.','inclination 在此指使人倾向于采取某种行动的意愿或偏好。','她主动讲解反映出对教学的偏好。')],mistakes:[M('Maya had no inclination to teach, so she eagerly volunteered to explain every topic at each meeting.','Maya showed an inclination to teach by volunteering to explain topics.','如果完全没有意愿，就不会主动承担讲解工作。')],quiz:[Q('inclination',1,1,'An inclination to travel is?','a desire or tendency to travel','a vertical wall','a legal prohibition','a desire or tendency to travel','inclination 可表示意愿或倾向。'),Q('inclination',2,2,'The inclination of a road is its?','slope away from level','number of travelers','quality of being readable','slope away from level','s2 指斜坡或倾斜角度。'),Q('inclination',3,1,'Which sentence uses inclination as a preference?','He has an inclination toward research.','The road’s inclination is steep.','The chart is an inclination.','He has an inclination toward research.','toward research 表明个人偏好。'),Q('inclination',4,1,'Inclination is related to the verb?','incline','include','incite','incline','inclination 由 incline 派生。','word-formation')]});
D('incline',{etymology:E('Incline comes from Latin inclinare, “to bend or lean.” As a verb it can mean tending to think or behave a certain way, making someone willing, or sloping; as a noun it means a slope or a natural preference.','incline'),contexts:[C('incline.s3','工程测量','The access road begins to incline sharply just beyond the bridge, so heavy trucks use the lower route.','通道在桥后不远处开始急剧倾斜，因此重型卡车改走较低的路线。','The access road begins to incline sharply / just beyond the bridge / so heavy trucks / use the lower route.','incline 在此作动词，表示向上或向下倾斜。','道路坡度在桥后明显变陡。')],mistakes:[M('The access road inclined by remaining perfectly flat and level from end to end.','The access road inclined by rising steeply beyond the bridge.','完全水平的道路没有倾斜。')],quiz:[Q('incline',1,1,'To incline toward a belief is to?','tend to think it is true','make it impossible to consider','draw a picture of it','tend to think it is true','incline 可表示倾向于某种看法。'),Q('incline',2,2,'A comment may incline someone to act by?','making them more willing','making them unable to hear','proving they already acted','making them more willing','s2 指使某人更愿意采取行动。'),Q('incline',3,3,'A road that inclines?','slopes or leans','is completely level','is difficult to read','slopes or leans','s3 作动词，表示倾斜。'),Q('incline',4,4,'An incline is?','a slope','a legal accusation','a group of people','a slope','s4 作名词表示斜坡。')]});
D('inclined',{etymology:E('Inclined is the past participle of incline and an adjective. It commonly means likely or willing to do something, especially because of a natural tendency or preference.','inclined'),contexts:[C('inclined.s1','团队讨论','After reviewing the evidence, the panel was inclined to recommend a pilot program rather than a permanent change.','审阅证据后，评审组倾向于建议先开展试点，而不是立刻永久改变。','After reviewing the evidence / the panel was inclined to recommend a pilot program / rather than / a permanent change.','inclined 表示有可能或倾向于做某事。','评审组更愿意先试点，显示一种倾向。')],mistakes:[M('The panel was inclined to approve the plan but was certain it would never consider approval.','The panel was inclined to approve the plan after reviewing the evidence.','倾向于批准与绝不考虑批准相矛盾。')],quiz:[Q('inclined',1,1,'Someone inclined to agree is?','likely or willing to agree','certainly forbidden to agree','unable to understand agreement','likely or willing to agree','inclined to 表示倾向于或愿意。'),Q('inclined',2,1,'Which person is inclined to help?','someone who naturally tends to offer assistance','someone who refuses every request','someone physically unable to move','someone who naturally tends to offer assistance','乐于主动帮忙的人有助人的倾向。'),Q('inclined',3,1,'“I am inclined to think so” means?','I tend to think so','I have proved it impossible','I am moving down a slope','I tend to think so','该短语表示倾向于这样认为。'),Q('inclined',4,1,'Inclined is related to the verb?','incline','incinerate','include','incline','inclined 是 incline 的分词形式。','word-formation')]});
D('include',{etymology:E('Include comes from Latin includere, “to shut or put in,” formed from in- and claudere, “to close.” It means having something as part of a group, making someone part of a group, or taking something into account.','include'),contexts:[C('include.s3','预算审查','The estimate includes shipping costs, so the final budget will not omit the expense of delivering the equipment.','这份估算把运费也计算在内，因此最终预算不会漏掉设备配送费用。','The estimate includes shipping costs / so the final budget / will not omit / the expense of delivering the equipment.','include 在此表示把某项费用考虑在总额之中。','运费已计入估算。')],mistakes:[M('The estimate included shipping costs but stated that the total deliberately left those costs out of account.','The estimate included shipping costs in the total.','included 表示纳入，而不是故意排除。')],quiz:[Q('include',1,1,'A package that includes three books?','has the books as part of it','contains none of the books','is a person’s preference','has the books as part of it','include 表示包含在内。'),Q('include',2,2,'To include a new member in a group is to?','make them part of the group','remove them from the group','ignore their existence','make them part of the group','s2 表示接纳某人进入群体。'),Q('include',3,3,'To include travel costs in a budget is to?','take them into account','leave them uncounted','turn them into income','take them into account','s3 指把费用考虑在内。'),Q('include',4,1,'Which list includes a pear?','apples, pears, and plums','apples and plums only','fruit that excludes pears','apples, pears, and plums','梨在清单所列项目之中。')]});
D('inclusion',{etymology:E('Inclusion comes from Latin inclusio, from includere, “to shut or put in.” It means the practice of including people or items, or a body enclosed within rock, a cell, or another material.','inclusion'),contexts:[C('inclusion.s1','教育政策','The school’s inclusion policy gives students with different learning needs access to the same classroom activities and support.','学校的包容政策让有不同学习需求的学生能够参与相同的课堂活动并获得支持。','The school’s inclusion policy / gives students with different learning needs / access to the same classroom activities / and support.','inclusion 在此指主动纳入原本可能被排除的人群。','政策为不同学生提供平等参与机会。')],mistakes:[M('The school described its inclusion policy as a way to exclude students who needed additional support.','The school described its inclusion policy as a way to involve students with different needs.','排除需要支持的学生与包容理念相反。')],quiz:[Q('inclusion',1,1,'Inclusion at school means?','ensuring people who might be left out can participate','removing some students from every activity','making a scientific measurement','ensuring people who might be left out can participate','inclusion 指包容和纳入参与。'),Q('inclusion',2,2,'A mineral inclusion in a rock is?','a body enclosed within the material','a person added to a school','a public event','a body enclosed within the material','s2 是岩石等材料中包裹的颗粒或物体。'),Q('inclusion',3,1,'Which policy promotes inclusion?','providing access and support to all learners','barring a group from class','offering help only to top scorers','providing access and support to all learners','公平参与和支持体现包容。'),Q('inclusion',4,1,'Inclusion is related to the verb?','include','incite','incline','include','inclusion 是 include 的名词形式。','word-formation')]});
D('inclusive',{etymology:E('Inclusive comes from Latin inclusivus, from includere, “to include.” It means counting the named items as part of a range, or being willing to accept people of different kinds.','inclusive'),contexts:[C('inclusive.s2','社区活动','The inclusive sports club welcomes children with different abilities and adapts the games so everyone can take part.','这个包容性体育俱乐部欢迎能力各异的儿童，并调整游戏方式，让每个人都能参加。','The inclusive sports club welcomes children with different abilities / and adapts the games / so everyone / can take part.','inclusive 在此形容愿意接纳不同人群并促使大家参与的。','俱乐部调整活动以便所有儿童都能加入。')],mistakes:[M('The club called itself inclusive while refusing entry to children with different abilities.','The club was inclusive because it adapted the games so children with different abilities could join.','拒绝特定群体参加不符合包容的含义。')],quiz:[Q('inclusive',1,1,'A date range inclusive of Monday includes?','Monday itself','only dates after Monday','no dates at all','Monday itself','inclusive 表示包含所提到的端点。'),Q('inclusive',2,2,'An inclusive club is willing to?','accept and involve people of different kinds','exclude everyone who needs support','count only its leaders','accept and involve people of different kinds','s2 指具有包容性、愿意接纳不同人群。'),Q('inclusive',3,1,'Which event is inclusive?','one adapted so everyone can take part','one that bars several groups','one with no participants allowed','one adapted so everyone can take part','调整安排使所有人参与体现包容。'),Q('inclusive',4,1,'Inclusive is related to the verb?','include','incinerate','incite','include','inclusive 与 include 同源。','word-formation')]});
D('incoherent',{etymology:E('Incoherent comes from Latin incohaerens, “not sticking together,” from in- and cohaerere, “to cohere.” It describes speech or writing that is confused and lacks clear connections.','incoherent'),contexts:[C('incoherent.s1','会议记录','The witness gave an incoherent account, jumping between dates and leaving the investigators unable to follow the sequence.','证人叙述混乱，时间日期前后跳跃，让调查人员无法理清顺序。','The witness gave an incoherent account / jumping between dates / and leaving the investigators / unable to follow the sequence.','incoherent 表示表达混乱、缺乏清晰连贯关系的。','叙述在日期间跳跃，难以追踪事件顺序。')],mistakes:[M('The report called the explanation incoherent even though it followed a clear sequence and connected every claim.','The report called the explanation coherent because it followed a clear sequence.','条理清楚且论点相连的解释不是 incoherent。')],quiz:[Q('incoherent',1,1,'An incoherent explanation is?','confused and lacking clear connections','clear and logically ordered','full of welcoming language','confused and lacking clear connections','incoherent 指不连贯、难以理解的。'),Q('incoherent',2,1,'Which account is incoherent?','one that jumps between dates without explaining the links','one that follows a clear timeline','one that defines every term carefully','one that jumps between dates without explaining the links','时间跳跃且缺少联系的叙述不连贯。'),Q('incoherent',3,1,'Incoherent is the opposite of?','coherent','inclement','incomplete','coherent','coherent 表示连贯，与 incoherent 相反。'),Q('incoherent',4,1,'The prefix in- in incoherent contributes?','not','before','within','not','in- 是否定前缀。','word-formation')]});
D('income',{etymology:E('Income combines in- with come, referring to money that comes in. It can mean money regularly received from work or investment, or the money a company or country receives.','income'),contexts:[C('income.s1','家庭预算','Their household income includes wages from both adults and interest earned on a small savings account.','这个家庭的收入包括两位成年人的工资以及小额储蓄账户的利息。','Their household income includes wages from both adults / and interest earned / on a small savings account.','income 在此指个人或家庭定期收到的钱。','工资和储蓄利息都是家庭收入来源。')],mistakes:[M('The budget listed wages as income but excluded all money the household regularly received from work.','The budget counted wages and savings interest as household income.','工资是家庭收到的收入，不能同时说被完全排除。')],quiz:[Q('income',1,1,'A person’s income is money received from?','work or investments','only money they spend','a legal penalty','work or investments','income 常指工资和投资收益。'),Q('income',2,2,'A company’s income is?','money the company receives','money it owes to every supplier only','the number of employees','money the company receives','s2 指公司或国家收到的资金。'),Q('income',3,1,'Which is income for a household?','regular wages','a bill the household must pay','a loan they have not received','regular wages','工资是家庭收入。'),Q('income',4,1,'Interest earned on savings may add to?','income','incoherence','inclement weather','income','储蓄利息可构成收入。')]});
D('incoming',{etymology:E('Incoming is formed from in- and coming. It describes something arriving or a person about to start a new job or term; it can also refer to money received.','incoming'),contexts:[C('incoming.s1','岗位交接','The outgoing director briefed the incoming director on current projects before the leadership change took effect.','领导层交接生效前，离任主任向即将上任的主任介绍了当前项目。','The outgoing director briefed the incoming director / on current projects / before the leadership change / took effect.','incoming 在此形容即将到任或开始新职位的人。','即将接任的主任在交接前听取项目简报。')],mistakes:[M('The incoming director had already left the job months earlier and would never start the role.','The incoming director was about to begin the role after the transition.','已离职且不会开始职位的人不是 incoming director。')],quiz:[Q('incoming',1,1,'An incoming train is?','arriving','already departed','impossible to move','arriving','incoming 表示正在到来或抵达。'),Q('incoming',2,1,'An incoming manager is?','about to start the job','leaving the company permanently','a person who reads poorly','about to start the job','s1 也指即将上任的人。'),Q('incoming',3,2,'Incoming funds are?','money received','money already spent','only unpaid taxes','money received','s2 指流入、收到的钱款。'),Q('incoming',4,1,'Which phrase is natural?','incoming calls from customers','incoming yesterday at the office','an incoming of a person','incoming calls from customers','incoming 可修饰即将接入的电话。','grammar')]});
D('incompatibility',{etymology:E('Incompatibility is formed from incompatible plus -ity. It means a situation in which two things cannot be combined, coexist, or work well together.','incompatibility'),contexts:[C('incompatibility.s1','软件支持','The technician traced the error to an incompatibility between the old printer driver and the new operating system.','技术人员把错误追溯到旧打印机驱动程序与新操作系统之间的不兼容。','The technician traced the error / to an incompatibility / between the old printer driver / and the new operating system.','incompatibility 指两种事物不能兼容或顺利配合的状况。','旧驱动与新系统无法协同运行。')],mistakes:[M('The technician blamed incompatibility even though the driver and operating system worked together perfectly.','The technician found incompatibility because the old driver failed with the new system.','能够完美协同的两者不构成不兼容。')],quiz:[Q('incompatibility',1,1,'Incompatibility means?','two things cannot work or fit together','two things support one another perfectly','a person’s annual wages','two things cannot work or fit together','incompatibility 指不兼容或难以共存。'),Q('incompatibility',2,1,'Which is an incompatibility?','a printer driver that fails with the new system','two devices that connect and operate correctly','a schedule that both teams accept','a printer driver that fails with the new system','驱动程序不能与系统配合运行。'),Q('incompatibility',3,1,'Incompatibility is the noun related to?','incompatible','income','incoming','incompatible','incompatibility 由 incompatible 加 -ity 构成。','word-formation'),Q('incompatibility',4,1,'A doctor might check for an incompatibility between?','two treatments that should not be combined','two compatible software updates','two identical pencils','two treatments that should not be combined','某些治疗方式可能不能同时使用。')]});
D('incompatible',{etymology:E('Incompatible combines the negative prefix in- with compatible, from Latin compatibilis, “able to coexist.” It means so different that two things cannot work or be true together.','incompatible'),contexts:[C('incompatible.s1','设备维护','The replacement battery was incompatible with the older camera, so the technician selected a model with the correct connector.','替换电池与旧款相机不兼容，因此技术人员选择了接口合适的型号。','The replacement battery was incompatible with the older camera / so the technician selected / a model / with the correct connector.','incompatible 表示两种事物无法协同工作或同时成立。','电池接口不匹配，无法与旧相机配合。')],mistakes:[M('The battery was called incompatible even though it fit the camera and powered it normally.','The battery was called compatible because it fit and powered the camera normally.','能正常配合工作的电池不是 incompatible。')],quiz:[Q('incompatible',1,1,'Incompatible software versions?','cannot work together properly','always function perfectly together','are impossible to install separately','cannot work together properly','incompatible 指不能兼容的。'),Q('incompatible',2,1,'Which pair is incompatible?','a plug that does not fit its socket','a key that opens its matching lock','a charger designed for the device','a plug that does not fit its socket','插头与插座不匹配，无法配合。'),Q('incompatible',3,1,'Incompatible beliefs cannot both be?','true or accepted together','written down','discussed','true or accepted together','两个互不相容的信念不能同时成立。'),Q('incompatible',4,1,'The prefix in- in incompatible means?','not','after','between','not','in- 在此是否定前缀。','word-formation')]});
D('incompetent',{etymology:E('Incompetent combines the negative prefix in- with competent, from Latin competere, “to be suitable or fit.” It describes someone lacking the skill to do a job properly or names such a person.','incompetent'),contexts:[C('incompetent.s1','服务评价','The audit found the contractor incompetent because repeated installation errors left the safety system unreliable.','审计认定承包商不称职，因为反复的安装错误导致安全系统不可靠。','The audit found the contractor incompetent / because repeated installation errors / left the safety system / unreliable.','incompetent 在此形容缺乏胜任工作所需技能的。','反复安装错误显示承包商未能胜任任务。')],mistakes:[M('The audit called the contractor incompetent even though the installation passed every test and had no defects.','The audit called the contractor competent because the installation passed every test.','工作通过测试且没有缺陷，不支持“不称职”的判断。')],quiz:[Q('incompetent',1,1,'An incompetent worker?','lacks the ability to do the job properly','performs the work reliably','has no assigned task','lacks the ability to do the job properly','incompetent 表示不胜任的。'),Q('incompetent',2,2,'As a noun, an incompetent is?','a person unable to do a job to an acceptable standard','a skilled expert','a person entering a country','a person unable to do a job to an acceptable standard','s2 可作名词，指不称职的人。'),Q('incompetent',3,1,'Which example suggests incompetence?','repeated errors that make a safety system unreliable','a flawless installation','a careful review before work','repeated errors that make a safety system unreliable','反复失误说明能力不足。'),Q('incompetent',4,1,'Incompetent is the opposite of?','competent','incoherent','inclement','competent','competent 表示胜任，与 incompetent 相反。')]});
D('incomplete',{etymology:E('Incomplete combines the negative prefix in- with complete, from Latin complere, “to fill or finish.” It means lacking a part or not yet brought to an end.','incomplete'),contexts:[C('incomplete.s1','申请审核','The application was returned as incomplete because the applicant had left the emergency contact section blank.','申请表因紧急联系人一栏空白而被退回，审核结果为材料不完整。','The application was returned as incomplete / because the applicant had left / the emergency contact section / blank.','incomplete 表示缺少部分内容或尚未完成。','一栏缺失使申请材料不完整。')],mistakes:[M('The form was incomplete because every section had been filled in and all required documents were attached.','The form was complete because every required section was filled in.','所有必填内容齐备时，表格不是 incomplete。')],quiz:[Q('incomplete',1,1,'An incomplete form?','is missing required information','contains every required detail','has already been approved','is missing required information','incomplete 表示不完整。'),Q('incomplete',2,1,'An incomplete project is?','not yet finished','fully completed','impossible to read','not yet finished','该词也可表示尚未结束。'),Q('incomplete',3,1,'Which makes an application incomplete?','leaving a required field blank','signing every required page','attaching all documents','leaving a required field blank','漏填必填栏会造成材料不完整。'),Q('incomplete',4,1,'The prefix in- contributes the sense?','not','before','very','not','in- 是否定前缀。','word-formation')]});
D('incompletely',{etymology:E('Incompletely is the adverb formed from incomplete plus -ly. It means not fully or only in part.','incompletely'),contexts:[C('incompletely.s1','数据录入','The clerk entered the customer records incompletely, leaving several required fields empty for later review.','职员没有完整录入客户记录，留下几个必填栏待之后复查。','The clerk entered the customer records incompletely / leaving several required fields / empty / for later review.','incompletely 表示不完全地、只完成一部分地。','必填栏仍为空，说明录入只完成了一部分。')],mistakes:[M('The records were entered incompletely even though every field was filled and checked twice.','The records were entered completely because every field was filled and checked.','全部填写并复核与不完整录入相矛盾。')],quiz:[Q('incompletely',1,1,'To report incompletely is to report?','only part of the information','every detail fully','nothing incorrectly','only part of the information','incompletely 表示不完整地。'),Q('incompletely',2,1,'Which task was done incompletely?','a form missing several required fields','a form checked and signed in every section','a finished report with all attachments','a form missing several required fields','缺少必填栏表明表格只填写了一部分。'),Q('incompletely',3,1,'Incompletely is the adverb from?','incomplete','incompetent','incompatible','incomplete','incompletely 由 incomplete 加 -ly 构成。','word-formation'),Q('incompletely',4,1,'If a wall is painted incompletely, some parts?','remain unpainted','are all perfectly covered','become a legal company','remain unpainted','部分墙面未涂说明工作不完整。')]});
D('incomprehensible',{etymology:E('Incomprehensible is formed from the negative prefix in-, comprehend, and -ible. It means so unclear or complex that it cannot be understood.','incomprehensible'),contexts:[C('incomprehensible.s1','技术说明','The manual’s first draft was incomprehensible to new users because it relied on unexplained abbreviations and missing steps.','说明手册的初稿对新用户来说难以理解，因为它使用未解释的缩写并漏掉了步骤。','The manual’s first draft was incomprehensible to new users / because it relied on unexplained abbreviations / and missing steps.','incomprehensible 表示复杂或含糊到无法理解的。','缩写未解释且步骤缺失，妨碍用户理解。')],mistakes:[M('The manual was incomprehensible even though every term was defined and each step was clearly explained.','The manual was comprehensible because every term and step was clearly explained.','解释清晰、步骤完整的手册并非难以理解。')],quiz:[Q('incomprehensible',1,1,'An incomprehensible message is?','too unclear or complex to understand','simple and direct','written in large print','too unclear or complex to understand','incomprehensible 表示难以理解的。'),Q('incomprehensible',2,1,'Which manual is incomprehensible?','one full of unexplained abbreviations and missing steps','one with clear terms and numbered steps','one reviewed by new users','one full of unexplained abbreviations and missing steps','未解释的缩写和缺失步骤让手册难懂。'),Q('incomprehensible',3,1,'Incomprehensible is the opposite of?','comprehensible','inconspicuous','inconclusive','comprehensible','comprehensible 表示可理解，与 incomprehensible 相反。'),Q('incomprehensible',4,1,'The ending -ible often means?','able to be','without','one who does','able to be','-ible 常表示能够被……。','word-formation')]});
D('inconceivable',{etymology:E('Inconceivable combines the negative prefix in- with conceivable, from conceive, “form an idea.” It means so strange or extreme that the mind cannot accept or imagine it.','inconceivable'),contexts:[C('inconceivable.s1','科学报道','Before the observatory opened, the scale of the newly mapped galaxy seemed inconceivable to the researchers.','天文台开放前，新绘制星系的规模对研究人员来说简直难以想象。','Before the observatory opened / the scale of the newly mapped galaxy / seemed inconceivable / to the researchers.','inconceivable 表示极其奇特或极端，以至于难以想象或接受。','星系规模巨大到超出研究人员的想象。')],mistakes:[M('The result was called inconceivable even though everyone had predicted it accurately for years.','The result seemed conceivable because it had been predicted accurately.','长期准确预测的结果并非难以想象。')],quiz:[Q('inconceivable',1,1,'An inconceivable event is?','so extreme or strange that it is hard to imagine','ordinary and expected','easy to read','so extreme or strange that it is hard to imagine','inconceivable 表示难以想象或接受的。'),Q('inconceivable',2,1,'Which possibility seems inconceivable?','a tiny room containing an entire mountain range','a bus arriving at its scheduled stop','a book containing printed pages','a tiny room containing an entire mountain range','小房间容纳山脉违背常理，难以想象。'),Q('inconceivable',3,1,'Inconceivable is related to the verb?','conceive','incinerate','include','conceive','conceivable/inconceivable 与 conceive（构想）相关。','word-formation'),Q('inconceivable',4,1,'If an outcome is inconceivable, people find it?','almost impossible to imagine','completely routine','already measured exactly','almost impossible to imagine','该词描述难以构想的结果。')]});
D('inconclusive',{etymology:E('Inconclusive is formed from in- and conclusive, from conclude, “bring to an end.” It describes evidence or a process that does not produce a clear conclusion.','inconclusive'),contexts:[C('inconclusive.s1','实验报告','The first test was inconclusive because the readings varied too widely to show whether the treatment had an effect.','第一次测试没有得出明确结论，因为读数波动太大，无法判断处理是否有效。','The first test was inconclusive / because the readings varied too widely / to show whether / the treatment had an effect.','inconclusive 表示不能得出清楚结论的。','数据波动过大，无法判断是否有效。')],mistakes:[M('The result was called inconclusive even though every measurement agreed and clearly established the outcome.','The result was conclusive because every measurement supported the same outcome.','数据一致并清楚证明结果时，结论并非不明确。')],quiz:[Q('inconclusive',1,1,'An inconclusive test?','does not produce a clear result','proves the answer beyond doubt','cannot be performed','does not produce a clear result','inconclusive 表示结果不确定、无法定论。'),Q('inconclusive',2,1,'Which evidence is inconclusive?','measurements that conflict and leave the outcome uncertain','repeated measurements that all agree','a signed final decision','measurements that conflict and leave the outcome uncertain','相互矛盾的数据不能支持明确结论。'),Q('inconclusive',3,1,'Inconclusive is the opposite of?','conclusive','incomplete','inconvenient','conclusive','conclusive 表示能得出结论。'),Q('inconclusive',4,1,'An inconclusive investigation may need?','more reliable evidence','no further information','a different spelling','more reliable evidence','还需证据才能得出明确结论。')]});
D('incongruity',{etymology:E('Incongruity is formed from incongruous plus -ity, from Latin congruere, “to agree or fit together.” It means a strange lack of fit between things that appear together.','incongruity'),contexts:[C('incongruity.s1','艺术评论','The critic noted the incongruity of a cheerful cartoon soundtrack playing over footage of a solemn memorial.','评论者指出，庄严纪念仪式的画面配上欢快卡通配乐，二者格格不入。','The critic noted the incongruity / of a cheerful cartoon soundtrack / playing over footage / of a solemn memorial.','incongruity 指并置事物之间奇怪的不协调。','欢快配乐与庄严纪念场景不相称。')],mistakes:[M('The reviewer found no incongruity between the solemn ceremony and playful clown music because both had the same tone.','The reviewer found an incongruity between the solemn ceremony and playful clown music.','庄严仪式与滑稽音乐语气相反，存在不协调。')],quiz:[Q('incongruity',1,1,'An incongruity is?','a strange lack of fit between things','a perfect match between styles','a clear conclusion','a strange lack of fit between things','incongruity 指不协调或不相称之处。'),Q('incongruity',2,1,'Which pairing contains incongruity?','solemn memorial footage with cheerful cartoon music','two matching colors in a uniform','a conclusion supported by its evidence','solemn memorial footage with cheerful cartoon music','庄严画面与欢快配乐格格不入。'),Q('incongruity',3,1,'Incongruity is related to?','incongruous','income','incineration','incongruous','incongruity 是 incongruous 的名词形式。','word-formation'),Q('incongruity',4,1,'A surprising mismatch may create?','incongruity','inclusion','inclement weather','incongruity','意外不匹配会形成不协调感。')]});
D('incongruous',{etymology:E('Incongruous comes from Latin incongruus, from in- and congruere, “to agree or fit together.” It describes something that looks or sounds out of place with its surroundings.','incongruous'),contexts:[C('incongruous.s1','建筑观察','The bright neon sign looked incongruous beside the historic stone doorway and its traditional carved lettering.','明亮的霓虹招牌放在历史悠久的石门旁显得格格不入，那里原有传统雕刻字样。','The bright neon sign looked incongruous / beside the historic stone doorway / and its traditional / carved lettering.','incongruous 表示与周围环境不协调、显得突兀的。','现代霓虹与传统石门风格不搭。')],mistakes:[M('The neon sign looked incongruous beside the matching modern storefront that used the same design and colors.','The neon sign looked incongruous beside the traditional stone doorway.','与周围现代店面一致的招牌并不突兀。')],quiz:[Q('incongruous',1,1,'An incongruous object looks?','out of place with its surroundings','perfectly matched to its setting','too small to measure','out of place with its surroundings','incongruous 表示不协调、格格不入的。'),Q('incongruous',2,1,'Which scene is incongruous?','a neon sign beside a centuries-old stone doorway','a wooden sign on a wooden fence','a lamp in a dark room','a neon sign beside a centuries-old stone doorway','现代霓虹与古老石门风格不搭。'),Q('incongruous',3,1,'Incongruous is closest to?','out of place','inconclusive','incompetent','out of place','out of place 与 incongruous 意思相近。'),Q('incongruous',4,1,'Incongruous is built around a root meaning?','agree or fit together','burn to ashes','receive money','agree or fit together','词根与协调、相合有关，in- 表示否定。','word-formation')]});
D('inconsiderate',{etymology:E('Inconsiderate combines the negative prefix in- with considerate, from Latin considerare, “to think about carefully.” It describes behavior that fails to consider how it affects others.','inconsiderate'),contexts:[C('inconsiderate.s1','公寓生活','Playing loud music late at night was inconsiderate because nearby residents had to wake early for work.','深夜大声播放音乐很不体贴，因为附近居民第二天一早还要上班。','Playing loud music late at night / was inconsiderate / because nearby residents / had to wake early for work.','inconsiderate 表示不顾及他人感受或处境的。','深夜噪音忽视了邻居的休息需要。')],mistakes:[M('The neighbor was inconsiderate by turning the music down and warning others before making noise.','The neighbor was considerate by reducing the noise and warning others.','主动降低噪音并提醒他人体现体贴，不是不体贴。')],quiz:[Q('inconsiderate',1,1,'An inconsiderate action?','ignores how it affects other people','carefully respects everyone’s needs','is impossible to imagine','ignores how it affects other people','inconsiderate 表示不替他人着想的。'),Q('inconsiderate',2,1,'Which behavior is inconsiderate?','making loud noise late at night near sleeping neighbors','lowering the volume when asked','warning neighbors before repairs','making loud noise late at night near sleeping neighbors','深夜噪音影响邻居休息，是不体贴的行为。'),Q('inconsiderate',3,1,'Inconsiderate is the opposite of?','considerate','incoherent','inconclusive','considerate','considerate 表示体贴，与 inconsiderate 相反。'),Q('inconsiderate',4,1,'The prefix in- in inconsiderate means?','not','many','before','not','in- 是否定前缀。','word-formation')]});
D('inconsistency',{etymology:E('Inconsistency is formed from inconsistent plus -cy. It means a lack of agreement or steadiness between statements, results, or actions.','inconsistency'),contexts:[C('inconsistency.s1','数据复核','The auditor found an inconsistency between the total shown on the summary page and the itemized receipts.','审计员发现摘要页上的总额与逐项收据之间存在不一致。','The auditor found an inconsistency / between the total shown on the summary page / and the itemized receipts.','inconsistency 指不同说法、结果或数据之间不一致。','汇总金额与收据明细对不上。')],mistakes:[M('The auditor reported an inconsistency even though the summary and every receipt showed exactly the same total.','The auditor reported consistency because the summary matched every receipt.','数据完全一致时不存在不一致。')],quiz:[Q('inconsistency',1,1,'An inconsistency between two reports is?','a lack of agreement','complete agreement','a legal permission','a lack of agreement','inconsistency 指不一致或矛盾。'),Q('inconsistency',2,1,'Which result shows inconsistency?','two tables give different totals for the same account','all copies show the same total','a report includes every required section','two tables give different totals for the same account','同一账户总额不同，说明数据不一致。'),Q('inconsistency',3,1,'Inconsistency is the noun related to?','inconsistent','income','incongruous','inconsistent','inconsistency 与 inconsistent 同源。','word-formation'),Q('inconsistency',4,1,'A reviewer checks for inconsistency to find?','claims or results that do not match','clear agreement across every page','a person’s income','claims or results that do not match','复核不一致性可找出矛盾数据。')]});
D('inconsistent',{etymology:E('Inconsistent combines the negative prefix in- with consistent, from Latin consistere, “to stand firm.” It describes changing without a steady pattern or failing to agree with other facts.','inconsistent'),contexts:[C('inconsistent.s1','质量检查','The machine produced inconsistent measurements, giving different readings when the same sample was tested repeatedly.','这台机器的测量结果不稳定，同一样本重复测试时读数各不相同。','The machine produced inconsistent measurements / giving different readings / when the same sample / was tested repeatedly.','inconsistent 表示缺乏稳定规律或彼此不一致的。','重复测量同一样本却得到不同数值。')],mistakes:[M('The measurements were inconsistent even though every repeated test returned the identical reading.','The measurements were consistent because each repeated test returned the same reading.','重复读数完全相同，不符合 inconsistent。')],quiz:[Q('inconsistent',1,1,'Inconsistent results?','do not follow a steady pattern','are identical every time','are impossible to read','do not follow a steady pattern','inconsistent 表示不稳定或不一致的。'),Q('inconsistent',2,1,'Which behavior is inconsistent?','following a different rule each day without reason','applying the same rule every day','recording identical measurements','following a different rule each day without reason','无故每天改变标准说明缺乏一致性。'),Q('inconsistent',3,1,'Inconsistent is the opposite of?','consistent','inconspicuous','inconsiderate','consistent','consistent 表示稳定一致。'),Q('inconsistent',4,1,'An inconsistent statement may?','conflict with another statement','match every known fact','be a clear illustration','conflict with another statement','前后矛盾的陈述互不一致。')]});
D('inconspicuous',{etymology:E('Inconspicuous is formed from the negative prefix in- and conspicuous, from Latin conspicere, “to look at.” It means not standing out and therefore easy to overlook.','inconspicuous'),contexts:[C('inconspicuous.s1','摄影观察','The small microphone was inconspicuous against the dark backdrop, so the audience barely noticed it.','小麦克风在深色背景前不显眼，观众几乎没有注意到它。','The small microphone was inconspicuous / against the dark backdrop / so the audience / barely noticed it.','inconspicuous 表示不引人注意、容易被忽略的。','设备与背景颜色接近，因此不显眼。')],mistakes:[M('The bright flashing sign was inconspicuous because everyone in the hall noticed it immediately.','The dark microphone was inconspicuous because it blended into the backdrop.','人人立刻注意到的闪光招牌并不隐蔽。')],quiz:[Q('inconspicuous',1,1,'An inconspicuous item?','does not stand out','attracts everyone’s attention','is difficult to combine','does not stand out','inconspicuous 表示不起眼的。'),Q('inconspicuous',2,1,'Which object is inconspicuous?','a small dark microphone blending into the wall','a flashing neon sign in a quiet room','a huge bright banner','a small dark microphone blending into the wall','与背景融合的小麦克风不显眼。'),Q('inconspicuous',3,1,'Inconspicuous is the opposite of?','conspicuous','incoherent','incomplete','conspicuous','conspicuous 表示显眼，与 inconspicuous 相反。'),Q('inconspicuous',4,1,'If something is inconspicuous, people may?','overlook it','notice it immediately','become immune to it','overlook it','不起眼的东西容易被忽视。')]});
D('inconspicuously',{etymology:E('Inconspicuously is the adverb formed from inconspicuous plus -ly. It means in a way that attracts little attention.','inconspicuously'),contexts:[C('inconspicuously.s1','博物馆参观','The guide placed the sign inconspicuously beside the doorway so it would inform visitors without distracting them from the exhibit.','导览员把标牌不显眼地放在门口旁边，让访客能看到信息，又不至于分散对展品的注意。','The guide placed the sign inconspicuously / beside the doorway / so it would inform visitors / without distracting them from the exhibit.','inconspicuously 表示不引人注意地。','标牌位置能提供信息而不抢展品风头。')],mistakes:[M('The sign was placed inconspicuously in the center of the gallery with flashing lights and a loud alarm.','The sign was placed inconspicuously beside the doorway without bright lights.','闪灯和警报会吸引注意，不是低调放置。')],quiz:[Q('inconspicuously',1,1,'To place an object inconspicuously is to place it?','so it attracts little attention','where everyone will stare','in a way that blocks all exits','so it attracts little attention','inconspicuously 表示不显眼地。'),Q('inconspicuously',2,1,'Which placement is inconspicuous?','a small sign beside the doorway','a giant flashing sign in the center','a loudspeaker blaring continuously','a small sign beside the doorway','门边的小标牌较不引人注目。'),Q('inconspicuously',3,1,'Inconspicuously is the adverb from?','inconspicuous','incidental','incompatible','inconspicuous','inconspicuously 由 inconspicuous 加 -ly 构成。','word-formation'),Q('inconspicuously',4,1,'A camera mounted inconspicuously is?','hard to notice','impossible to operate','very expensive','hard to notice','隐蔽安装的摄像机不容易被注意到。')]});
D('inconvenient',{etymology:E('Inconvenient combines the negative prefix in- with convenient, from Latin convenire, “to come together or be suitable.” It means not convenient and likely to cause bother.','inconvenient'),contexts:[C('inconvenient.s1','出行安排','The road closure is inconvenient for commuters because the replacement bus stop is several blocks away.','道路封闭给通勤者带来不便，因为临时公交站在几个街区之外。','The road closure is inconvenient for commuters / because the replacement bus stop / is several blocks away.','inconvenient 表示不方便、可能造成麻烦的。','临时车站距离较远，增加通勤麻烦。')],mistakes:[M('The new stop was inconvenient even though it stood directly outside the office and reduced everyone’s commute.','The new stop was convenient because it stood outside the office.','车站就在办公室门口并缩短通勤，不符合不便的含义。')],quiz:[Q('inconvenient',1,1,'An inconvenient time is?','awkward or troublesome','perfectly suitable for everyone','a cause of great happiness','awkward or troublesome','inconvenient 表示不方便的。'),Q('inconvenient',2,1,'Which change is inconvenient for commuters?','moving the stop several blocks away','adding a stop beside the office','keeping the same easy route','moving the stop several blocks away','车站变远会增加通勤不便。'),Q('inconvenient',3,1,'Inconvenient is the opposite of?','convenient','incomplete','inconclusive','convenient','convenient 表示方便，与 inconvenient 相反。'),Q('inconvenient',4,1,'The prefix in- means?','not','together','after','not','in- 是否定前缀。','word-formation')]});
D('incorporate',{etymology:E('Incorporate comes from Latin incorporare, “to form into a body,” from in- and corpus, “body.” It can mean including something in a whole, combining things, legally forming a company, or being formed into one body.','incorporate'),contexts:[C('incorporate.s1','产品设计','The team will incorporate recycled glass into the new tile mixture while keeping the surface strong and easy to clean.','团队将把再生玻璃纳入新瓷砖配方，同时保持表面坚固且易于清洁。','The team will incorporate recycled glass / into the new tile mixture / while keeping the surface / strong and easy to clean.','incorporate 在此表示把一种材料纳入更大的整体。','再生玻璃成为瓷砖配方的一部分。')],mistakes:[M('The recipe incorporated salt by leaving it out of the mixture entirely.','The recipe incorporated salt by adding it to the mixture.','完全不加入材料就不能说把它纳入配方。')],quiz:[Q('incorporate',1,1,'To incorporate a suggestion is to?','include it as part of a larger plan','ignore it completely','make it impossible to understand','include it as part of a larger plan','incorporate 可表示纳入整体。'),Q('incorporate',2,2,'To incorporate two ingredients may mean to?','combine them into one mixture','keep them permanently apart','make them into legal companies','combine them into one mixture','s2 指将两种事物结合起来。'),Q('incorporate',3,3,'A business may incorporate when it?','forms a legal corporation','adds salt to a recipe','joins a classroom discussion','forms a legal corporation','s3 指依法成立公司。'),Q('incorporate',4,4,'A body incorporated into a group is?','formed or joined into one whole','kept entirely separate','unable to move','formed or joined into one whole','s4 描述被整合成一个整体。')]});
D('incorporation',{etymology:E('Incorporation is formed from incorporate plus -ion. It means making one thing part of a larger whole or legally creating a company as a corporation.','incorporation'),contexts:[C('incorporation.s2','企业登记','The founders completed the incorporation documents so the new company could enter contracts in its own legal name.','创始人完成了公司注册文件，使新公司能够以自己的法定名称签订合同。','The founders completed the incorporation documents / so the new company / could enter contracts / in its own legal name.','incorporation 在此指依法成立公司的过程。','注册后，公司可用自己的法定名称订立合同。')],mistakes:[M('The founders described incorporation as closing the company permanently and removing its legal identity.','The founders completed incorporation to create the company as a legal corporation.','公司注册是建立法人身份，不是注销公司。')],quiz:[Q('incorporation',1,1,'Incorporation of a feature into a design means?','making it part of the larger design','removing it from the design','making it a legal person','making it part of the larger design','incorporation 可指纳入整体的过程。'),Q('incorporation',2,2,'The incorporation of a company is its?','legal creation as a corporation','closure after insolvency','first public advertisement','legal creation as a corporation','s2 指依法成立公司。'),Q('incorporation',3,1,'Which paperwork relates to incorporation?','documents registering a new company','a hotel room reservation','a patient’s vaccination record','documents registering a new company','公司登记文件与 incorporation 相关。'),Q('incorporation',4,1,'Incorporation is the noun related to?','incorporate','income','inclement','incorporate','incorporation 由 incorporate 派生。','word-formation')]});
D('incorporeal',{etymology:E('Incorporeal combines the negative prefix in- with corporeal, from Latin corporeus, “bodily,” based on corpus, “body.” It means not consisting of matter and existing without a body.','incorporeal'),contexts:[C('incorporeal.s1','哲学讨论','The philosopher used incorporeal for an imagined spirit that has no physical body or material substance.','哲学家用 incorporeal 描述一种没有物理身体或物质实体的想象中的灵体。','The philosopher used incorporeal / for an imagined spirit / that has no physical body / or material substance.','incorporeal 表示非物质的、没有实体身体的。','灵体被设定为不存在物理躯体。')],mistakes:[M('The metal statue was called incorporeal even though it had weight, volume, and a solid body.','The imagined spirit was called incorporeal because it had no physical body.','有重量、体积和实体的雕像不是非物质的。')],quiz:[Q('incorporeal',1,1,'An incorporeal being is?','not made of matter and without a body','a heavy physical statue','easy to read','not made of matter and without a body','incorporeal 表示非物质、无形体的。'),Q('incorporeal',2,1,'Which concept is incorporeal?','a spirit imagined to have no physical body','a stone with measurable weight','a wooden chair','a spirit imagined to have no physical body','无物质身体的灵体概念符合该义。'),Q('incorporeal',3,1,'Incorporeal is the opposite of?','corporeal','incoherent','inconvenient','corporeal','corporeal 表示有形体的，与 incorporeal 相反。'),Q('incorporeal',4,1,'The root corpus means?','body','light','law','body','corpus 意为身体或实体。','word-formation')]});
D('incorrect',{etymology:E('Incorrect combines the negative prefix in- with correct, from Latin correctus, “made straight or set right.” It means not right or not accurate.','incorrect'),contexts:[C('incorrect.s1','作业批改','The teacher marked the answer incorrect because the student had used the wrong unit in the final calculation.','老师把答案判为错误，因为学生在最后计算中用了错误的单位。','The teacher marked the answer incorrect / because the student had used / the wrong unit / in the final calculation.','incorrect 表示不正确或不准确的。','单位错误使最终答案不准确。')],mistakes:[M('The teacher marked the answer incorrect even though it matched the correct value and used the proper units.','The teacher marked the answer correct because it matched the value and units.','数值与单位都正确时，不应判为 incorrect。')],quiz:[Q('incorrect',1,1,'An incorrect answer is?','not right','fully accurate','impossible to see','not right','incorrect 表示错误的。'),Q('incorrect',2,1,'Which statement is incorrect?','one that contradicts verified facts','one supported by the evidence','one copied accurately from the source','one that contradicts verified facts','与已核实事实矛盾的说法不正确。'),Q('incorrect',3,1,'Incorrect is the opposite of?','correct','inclement','incoherent','correct','correct 表示正确。'),Q('incorrect',4,1,'The prefix in- in incorrect means?','not','before','together','not','in- 是否定前缀。','word-formation')]});
D('incorrectly',{etymology:E('Incorrectly is the adverb formed from incorrect plus -ly. It means in a wrong or inaccurate way.','incorrectly'),contexts:[C('incorrectly.s1','实验记录','The technician initially entered the temperature incorrectly, then corrected the value after checking the instrument.','技术员最初错误地记录了温度，检查仪器后才改正数值。','The technician initially entered the temperature incorrectly / then corrected the value / after checking / the instrument.','incorrectly 表示以错误或不准确的方式。','初次记录的温度与仪器读数不符。')],mistakes:[M('The technician entered the temperature incorrectly, but the recorded value exactly matched the calibrated instrument.','The technician entered the temperature correctly because it matched the calibrated instrument.','与校准仪器完全一致说明记录正确。')],quiz:[Q('incorrectly',1,1,'To label a package incorrectly is to label it?','in the wrong way','with complete accuracy','without any label','in the wrong way','incorrectly 表示错误地。'),Q('incorrectly',2,1,'Which sentence uses incorrectly correctly?','The form was filled in incorrectly and had to be redone.','The form incorrectly by the clerk.','Incorrectly is an adjective naming a form.','The form was filled in incorrectly and had to be redone.','错误填写后需要重做。'),Q('incorrectly',3,1,'Incorrectly is the adverb from?','incorrect','incredible','inclusion','incorrect','incorrectly 由 incorrect 加 -ly 构成。','word-formation'),Q('incorrectly',4,1,'If a number is entered incorrectly, it is?','entered inaccurately','entered with no error','entered twice in the right place','entered inaccurately','该副词表示录入有误。')]});
D('incorruptible',{etymology:E('Incorruptible combines the negative prefix in- with corruptible, from Latin corrumpere, “to corrupt.” It describes a person unwilling to take bribes or abandon moral standards.','incorruptible'),contexts:[C('incorruptible.s1','公共服务','Residents trusted the incorruptible inspector because she refused gifts and applied the same rules to every contractor.','居民信任这位廉洁的检查员，因为她拒收礼物，并对每个承包商一视同仁。','Residents trusted the incorruptible inspector / because she refused gifts / and applied the same rules / to every contractor.','incorruptible 表示不受贿赂诱惑、坚守道德标准的。','拒绝礼物并公平执法显示其廉洁。')],mistakes:[M('The inspector was called incorruptible after accepting cash to overlook safety violations.','The inspector was called corrupt because she accepted money to ignore violations.','收钱忽视违规正是腐败行为，不符合廉洁义。')],quiz:[Q('incorruptible',1,1,'An incorruptible official?','refuses bribes and keeps moral standards','changes decisions for gifts','is unable to read','refuses bribes and keeps moral standards','incorruptible 表示廉洁、不受腐蚀的。'),Q('incorruptible',2,1,'Which behavior is incorruptible?','applying rules fairly despite pressure','taking a bribe to favor a contractor','hiding a conflict of interest','applying rules fairly despite pressure','顶住压力公平执行规则体现廉洁。'),Q('incorruptible',3,1,'Incorruptible is the opposite of?','corruptible','incomplete','inconspicuous','corruptible','corruptible 表示可被腐蚀的。'),Q('incorruptible',4,1,'The prefix in- contributes the meaning?','not','again','very','not','in- 是否定前缀。','word-formation')]});
D('increase',{etymology:E('Increase comes from Old French encreistre and Latin increscere, “to grow.” It can mean becoming greater, making something larger, a rise in amount, or the act of growing.','increase'),contexts:[C('increase.s2','能源统计','The utility increased its solar capacity by adding panels to three public buildings.','公用事业公司通过在三座公共建筑上加装太阳能板，扩大了太阳能容量。','The utility increased its solar capacity / by adding panels / to three public buildings.','increase 在此作及物动词，表示使某个数量或规模变大。','增装面板使太阳能容量提高。')],mistakes:[M('The utility increased its capacity by removing panels and reducing the amount of power it could generate.','The utility increased its capacity by adding panels and raising potential output.','移除面板并降低发电量不是增加容量。')],quiz:[Q('increase',1,1,'If attendance increases, it?','becomes greater','becomes smaller','stays exactly the same','becomes greater','increase 作不及物动词表示增长。'),Q('increase',2,2,'To increase the budget is to?','make it larger','spend none of it','explain it more clearly','make it larger','s2 作及物动词表示增加某物。'),Q('increase',3,3,'An increase in rainfall is?','a rise in the amount of rain','the act of rainfall stopping','a decrease in cloud cover','a rise in the amount of rain','increase 作名词可指数量上升。'),Q('increase',4,4,'The increase of a balloon’s size describes?','the act of becoming larger','a list of related words','a final legal judgment','the act of becoming larger','s4 指变大的过程或行为。')]});
D('increasingly',{etymology:E('Increasingly is the adverb formed from increasing plus -ly. It means to a greater extent as time passes or as a process continues.','increasingly'),contexts:[C('increasingly.s1','城市交通','Residents are increasingly choosing bicycles for short trips as the city adds protected lanes.','随着城市增设受保护的自行车道，居民越来越多地选择骑车完成短途出行。','Residents are increasingly choosing bicycles / for short trips / as the city adds / protected lanes.','increasingly 表示程度逐渐增加地。','随着自行车道增加，选择骑车的人越来越多。')],mistakes:[M('The report said residents were increasingly choosing bicycles, although the share fell steadily every year.','The report said bicycle use was decreasing because its share fell each year.','份额持续下降不支持“越来越多地选择”。')],quiz:[Q('increasingly',1,1,'If something happens increasingly often, it happens?','more often as time passes','less often each time','only once','more often as time passes','increasingly 表示程度逐渐增加。'),Q('increasingly',2,1,'Which sentence uses increasingly naturally?','The town is increasingly relying on renewable power.','The town increasingly yesterday the street.','Increasingly is the noun for a power plant.','The town is increasingly relying on renewable power.','该副词可修饰逐渐增强的依赖。'),Q('increasingly',3,1,'Increasingly is related to which verb?','increase','incise','incinerate','increase','increasingly 由 increase 派生。','word-formation'),Q('increasingly',4,1,'An increasingly popular event is becoming?','more popular over time','less popular each year','impossible to attend','more popular over time','increasingly popular 表示越来越受欢迎。')]});
D('incredible',{etymology:E('Incredible comes from Latin incredibilis, “not to be believed,” formed from in- and credibilis. It can mean hard to believe, extremely great in degree, or informally extremely good.','incredible'),contexts:[C('incredible.s1','科学新闻','The researchers described the signal as incredible because it was far stronger than any earlier measurement.','研究人员称这个信号难以置信，因为它远强于此前任何一次测量结果。','The researchers described the signal as incredible / because it was far stronger / than any earlier measurement.','incredible 在此表示难以相信的。','信号强度远超已有记录，令人难以置信。')],mistakes:[M('The signal was called incredible even though it matched ordinary readings and surprised no one.','The signal was called incredible because it greatly exceeded all earlier readings.','普通且无惊人之处的读数不符合难以置信的含义。')],quiz:[Q('incredible',1,1,'An incredible claim is?','very difficult to believe','certainly true and ordinary','impossible to say aloud','very difficult to believe','incredible 可表示难以置信的。'),Q('incredible',2,2,'An incredible increase may be?','extremely great in degree','a tiny routine change','a legal company','extremely great in degree','s2 表示程度极大。'),Q('incredible',3,3,'In casual praise, “The concert was incredible” means it was?','extremely good','impossible to attend','not important','extremely good','s3 是口语中的“精彩极了”。'),Q('incredible',4,1,'Incredible is formed with a prefix meaning?','not','again','under','not','in- 否定 credible。','word-formation')]});
D('incredulity',{etymology:E('Incredulity comes from Latin incredulitas, from incredulus, “unbelieving,” and credere, “to believe.” It means refusal or inability to believe something surprising.','incredulity'),contexts:[C('incredulity.s1','新闻反应','The audience listened in incredulity as the presenter announced that the tiny seed had survived a year in space.','听到主持人宣布这颗小种子在太空中存活了一年，观众难以置信地听着。','The audience listened in incredulity / as the presenter announced / that the tiny seed / had survived a year in space.','incredulity 指对令人惊讶的事情不相信或难以相信。','种子在太空存活一年出乎意料，引发怀疑。')],mistakes:[M('The audience showed incredulity because they immediately believed the surprising story without question.','The audience showed credulity by accepting the surprising story immediately.','不加怀疑地接受故事是轻信，不是 incredulity。')],quiz:[Q('incredulity',1,1,'Incredulity is?','difficulty or refusal to believe','strong confidence in a familiar fact','a growing amount','difficulty or refusal to believe','incredulity 指不相信或难以置信。'),Q('incredulity',2,1,'A person may react with incredulity to?','a surprising claim that seems impossible','a routine announcement they expected','a clearly printed schedule','a surprising claim that seems impossible','令人震惊、难以接受的说法会引起怀疑。'),Q('incredulity',3,1,'Incredulity is related to?','incredulous','increasingly','inclement','incredulous','incredulity 是 incredulous 的名词形式。','word-formation'),Q('incredulity',4,1,'Which expression shows incredulity?','“You cannot be serious!”','“I expected exactly that.”','“Thank you for the clear directions.”','“You cannot be serious!”','这句话表现出不相信对方的话。')]});
D('incredulous',{etymology:E('Incredulous comes from Latin incredulus, “unbelieving,” from in- and credere, “to believe.” It describes someone showing that they do not believe what has been said.','incredulous'),contexts:[C('incredulous.s1','旅行访谈','Mina gave the guide an incredulous look when he said the mountain trail was only five minutes long.','导游说山路只需五分钟时，米娜用难以置信的目光看着他。','Mina gave the guide an incredulous look / when he said / the mountain trail / was only five minutes long.','incredulous 形容表现出不相信的。','米娜对明显夸大的路程时间表示怀疑。')],mistakes:[M('Mina looked incredulous because she immediately accepted the unlikely claim as completely ordinary.','Mina looked credulous because she accepted the unlikely claim without question.','毫不怀疑地接受说法与 incredulous 相反。')],quiz:[Q('incredulous',1,1,'An incredulous listener?','does not believe what was said','accepts every claim without question','is eager to start a new job','does not believe what was said','incredulous 指不相信对方所说内容的。'),Q('incredulous',2,1,'Which reaction is incredulous?','raising an eyebrow at an unlikely explanation','nodding because the facts are familiar','writing down an ordinary date','raising an eyebrow at an unlikely explanation','对不太可能的解释扬眉表示怀疑。'),Q('incredulous',3,1,'Incredulous is related to the noun?','incredulity','income','incursion','incredulity','incredulous 与 incredulity 同源。','word-formation'),Q('incredulous',4,1,'An incredulous expression may communicate?','“I find that hard to believe.”','“I completely agree.”','“I am falling asleep.”','“I find that hard to believe.”','难以置信的表情传达怀疑。')]});
D('increment',{etymology:E('Increment comes from Latin incrementum, from increscere, “to grow.” It means a usually small amount by which something grows or one step in a series of additions.','increment'),contexts:[C('increment.s1','薪资制度','The contract raises the employee’s pay by a small annual increment rather than by a single large adjustment.','合同规定员工工资每年小幅递增，而不是一次性大幅调整。','The contract raises the employee’s pay / by a small annual increment / rather than / by a single large adjustment.','increment 在此指工资逐步增加的一小部分。','年度增幅是分阶段的薪资增长量。')],mistakes:[M('The contract called a pay cut of 10 percent an increment in salary.','The contract called a small pay rise an increment.','减薪不是工资增量。')],quiz:[Q('increment',1,1,'An increment is usually?','a small amount added to something','a complete removal','a person’s disbelief','a small amount added to something','increment 常指逐步增加的一小部分。'),Q('increment',2,2,'An increment in a sequence may be?','one small step of addition','the final total only','an unrelated event','one small step of addition','s2 指连续增加中的一个小步骤。'),Q('increment',3,1,'Which example is an increment?','a two-dollar annual raise','a full-time job title','a decrease in every payment','a two-dollar annual raise','小幅年度加薪是 increment。'),Q('increment',4,1,'Increment is related to the idea of?','growth','refusal to believe','stormy weather','growth','increment 与逐渐增长相关。','word-formation')]});
D('incriminate',{etymology:E('Incriminate comes from Latin criminari, “to accuse,” from crimen, “crime.” It means showing or suggesting that someone was involved in a crime.','incriminate'),contexts:[C('incriminate.s1','案件调查','The timestamped recording appeared to incriminate the suspect by placing him at the locked storage room during the theft.','带时间戳的录像似乎使嫌疑人涉嫌盗窃，因为录像显示他在失窃时出现在上锁的仓库。','The timestamped recording appeared to incriminate the suspect / by placing him / at the locked storage room / during the theft.','incriminate 表示使某人显得涉案或提供其涉案证据。','录像将嫌疑人与案发地点和时间联系起来。')],mistakes:[M('The recording incriminated the suspect by proving he was elsewhere and had no connection to the theft.','The recording cleared the suspect because it showed he was elsewhere.','证明嫌疑人在别处会为其开脱，而非使其涉案。')],quiz:[Q('incriminate',1,1,'Evidence incriminates someone when it?','suggests they were involved in a crime','proves they were elsewhere','shows they are immune to illness','suggests they were involved in a crime','incriminate 表示提供涉案证据。'),Q('incriminate',2,1,'Which detail could incriminate a suspect?','a recording places them at the scene during the theft','a receipt shows they were in another city','a witness confirms they were at home','a recording places them at the scene during the theft','案发时出现在现场的录像可能使嫌疑人涉案。'),Q('incriminate',3,1,'Incriminate is related to a Latin word for?','crime','growth','image','crime','词源 crimen 意为罪行。','word-formation'),Q('incriminate',4,1,'A witness should avoid saying evidence incriminates someone unless it?','supports a connection to wrongdoing','clears the person entirely','has no relevance','supports a connection to wrongdoing','该词表示证据把人和不当行为联系起来。')]});
D('incubate',{etymology:E('Incubate comes from Latin incubare, “to lie upon,” from in- and cubare, “to lie down.” It means keeping eggs warm until they hatch.','incubate'),contexts:[C('incubate.s1','鸟类观察','The conservation team used a temperature-controlled cabinet to incubate the rescued eggs until they were ready to hatch.','保护团队用恒温箱孵化获救的鸟蛋，直到它们即将破壳。','The conservation team used a temperature-controlled cabinet / to incubate the rescued eggs / until they were ready / to hatch.','incubate 表示保持鸟蛋温暖直到孵化。','恒温箱为蛋提供孵化所需的温度条件。')],mistakes:[M('The team incubated the eggs by leaving them in a cold room where they could not develop.','The team incubated the eggs in a warm, temperature-controlled cabinet.','低温环境不能提供孵化所需的温暖条件。')],quiz:[Q('incubate',1,1,'To incubate eggs is to?','keep them warm until they hatch','freeze them permanently','paint pictures on them','keep them warm until they hatch','incubate 的生物学义是孵蛋。'),Q('incubate',2,1,'Which device can incubate eggs?','a temperature-controlled cabinet','a cold storage freezer','a printing press','a temperature-controlled cabinet','孵化箱可以控制温度以孵蛋。'),Q('incubate',3,1,'The Latin source of incubate referred to?','lying upon','cutting into stone','moving into a country','lying upon','词源与伏卧在上、覆盖孵育有关。','word-formation'),Q('incubate',4,1,'A bird incubates eggs so that they can?','develop and hatch','become a legal company','increase in price','develop and hatch','鸟类孵蛋使胚胎发育并孵化。')]});
D('incubation',{etymology:E('Incubation is formed from incubate plus -ion. It can mean keeping eggs warm until they hatch or the period in which a disease or idea develops before becoming apparent.','incubation'),contexts:[C('incubation.s2','健康科普','The nurse explained that the incubation period is the time between infection and the first noticeable symptoms.','护士解释说，潜伏期是从感染到首次出现明显症状之间的时间。','The nurse explained / that the incubation period / is the time between infection / and the first noticeable symptoms.','incubation 在此指疾病在症状出现前发展的潜伏期。','句中说明感染与症状出现之间的阶段。')],mistakes:[M('The report defined incubation as the period after all symptoms had ended and recovery was complete.','The report defined incubation as the period before symptoms first appear.','症状消失后的恢复期不是 incubation period。')],quiz:[Q('incubation',1,1,'Egg incubation is the process of?','keeping eggs warm until they hatch','freezing eggs for storage','counting the birds after hatching','keeping eggs warm until they hatch','incubation 可指孵蛋过程。'),Q('incubation',2,2,'A disease’s incubation period is?','the time from infection until symptoms appear','the period after all symptoms disappear','the time needed to read a report','the time from infection until symptoms appear','s2 指疾病潜伏期。'),Q('incubation',3,1,'Which sentence uses incubation in medicine?','The incubation period was five days.','The incubation was a legal corporation.','The doctor incubated the patient’s salary.','The incubation period was five days.','incubation period 是潜伏期。'),Q('incubation',4,1,'Incubation is related to which verb?','incubate','incriminate','include','incubate','incubation 是 incubate 的名词形式。','word-formation')]});
D('incubator',{etymology:E('Incubator is formed from incubate plus -or, a suffix naming a person or device that performs an action. It can be a machine maintaining safe conditions for eggs or premature babies, or an organization supporting new companies.','incubator'),contexts:[C('incubator.s1','新生儿护理','The neonatal incubator maintains a stable temperature for the premature baby while clinical staff monitor the infant’s condition.','新生儿保温箱为早产儿维持稳定温度，医护人员同时监测婴儿状况。','The neonatal incubator maintains a stable temperature / for the premature baby / while clinical staff / monitor the infant’s condition.','incubator 在此指为早产儿维持安全环境的设备。','设备维持温度并配合医护监护。')],mistakes:[M('The hospital used an incubator by exposing the premature infant to uncontrolled cold air.','The hospital used an incubator to maintain a stable, safe temperature for the infant.','将婴儿暴露在不受控冷空气中违背保温箱的作用。')],quiz:[Q('incubator',1,1,'A medical incubator helps by?','maintaining a safe temperature for a premature baby','measuring a person’s income','making a room inconspicuous','maintaining a safe temperature for a premature baby','incubator 可为早产儿提供受控环境。'),Q('incubator',2,2,'A business incubator supports?','new companies as they grow','eggs only','a legal trial','new companies as they grow','s2 指扶持初创公司的组织。'),Q('incubator',3,1,'Which device is an incubator?','a controlled cabinet for eggs or premature infants','a household income record','a reading lamp','a controlled cabinet for eggs or premature infants','可控温的孵化或保育设备是 incubator。'),Q('incubator',4,1,'Incubator is formed from incubate plus?','-or','-less','-ity','-or','-or 常指执行动作的人或设备。','word-formation')]});
D('inculcate',{etymology:E('Inculcate comes from Latin inculcare, “to tread in,” from in- and calcare, “to tread.” It means teaching an attitude or habit through long, repeated instruction.','inculcate'),contexts:[C('inculcate.s1','学校教育','The coach tried to inculcate respect for opponents by modeling fair play at every practice.','教练通过每次训练都示范公平竞赛，努力培养队员对对手的尊重。','The coach tried to inculcate respect for opponents / by modeling fair play / at every practice.','inculcate 表示通过长期反复教导使人形成态度或习惯。','每次练习都示范公平竞赛，持续培养尊重。')],mistakes:[M('The coach inculcated fairness by telling players never to respect opponents or follow rules.','The coach inculcated fairness by repeatedly modeling respect and rule-following.','反复教导违反公平的做法不会培养公平态度。')],quiz:[Q('inculcate',1,1,'To inculcate a habit is to?','teach it through repeated instruction','mention it once without explanation','make it impossible to learn','teach it through repeated instruction','inculcate 指通过反复教导培养习惯。'),Q('inculcate',2,1,'A teacher may inculcate respect by?','consistently modeling and reinforcing it','mocking respectful behavior','never discussing conduct','consistently modeling and reinforcing it','持续示范与强化能培养尊重。'),Q('inculcate',3,1,'Inculcate is most closely connected with?','instilling an attitude over time','measuring a slope','burning waste','instilling an attitude over time','该词描述逐渐灌输、培养观念。'),Q('inculcate',4,1,'The Latin source of inculcate referred to?','treading in','moving into a country','forming an image','treading in','词源字面意象是反复踏入、灌输。','word-formation')]});
D('incumbency',{etymology:E('Incumbency is formed from incumbent plus -cy. It means the state or period of holding an official position.','incumbency'),contexts:[C('incumbency.s1','选举报道','During her incumbency as mayor, the city completed the bridge repair and expanded the public library.','在她担任市长期间，市里完成了桥梁维修并扩建了公共图书馆。','During her incumbency as mayor / the city completed the bridge repair / and expanded / the public library.','incumbency 指担任某个公职的状态或任期。','句子限定了市长任职期间完成的工作。')],mistakes:[M('The article discussed the mayor’s incumbency after she had never held the office at any time.','The article discussed her incumbency during the years she served as mayor.','从未担任过该职位的人没有 incumbency。')],quiz:[Q('incumbency',1,1,'Incumbency is the state of?','holding an official position','being unable to understand','moving into a country','holding an official position','incumbency 指在任状态或任期。'),Q('incumbency',2,1,'A report about a mayor’s incumbency covers?','the period when the mayor held office','the mayor’s childhood only','the election before any candidate entered office','the period when the mayor held office','incumbency 讨论任职期间。'),Q('incumbency',3,1,'Incumbency is related to which adjective or noun?','incumbent','incomplete','incoherent','incumbent','incumbency 由 incumbent 派生。','word-formation'),Q('incumbency',4,1,'Which phrase is natural?','during her incumbency as governor','her incumbency of a horseshoe','incumbency the meeting loudly','during her incumbency as governor','during one’s incumbency 表示任职期间。')]});
D('incumbent',{etymology:E('Incumbent comes from Latin incumbens, “resting upon,” from incumbere, “to lean upon.” It can describe someone currently holding office, a duty resting on someone, or the current officeholder as a noun.','incumbent'),contexts:[C('incumbent.s3','选举现场','The incumbent won another term after voters compared her record with those of the challengers.','选民比较她与挑战者的政绩后，现任者赢得了新一届任期。','The incumbent won another term / after voters compared her record / with those / of the challengers.','incumbent 在此作名词，指目前担任某职位的人。','现任者与挑战者竞争连任。')],mistakes:[M('The candidate was called the incumbent despite never having held the office and running against its current holder.','The candidate challenging the current officeholder was not the incumbent.','从未担任该职位的挑战者不是现任者。')],quiz:[Q('incumbent',1,1,'An incumbent official is?','currently holding the office','running for the first time without holding it','retired decades ago','currently holding the office','incumbent 作形容词指现任的。'),Q('incumbent',2,2,'A duty incumbent on a manager is?','a responsibility resting on that manager','a prize the manager has won','an office the manager has left','a responsibility resting on that manager','s2 指由某人承担的责任。'),Q('incumbent',3,3,'As a noun, the incumbent is?','the person currently holding a position','a person who has never sought the role','a person who is unable to read','the person currently holding a position','s3 指现任职者。'),Q('incumbent',4,1,'Which pair is correct?','incumbent mayor: current mayor','incumbent mayor: former mayor only','incumbent mayor: a mayoral candidate with no office','incumbent mayor: current mayor','incumbent mayor 指现任市长。')]});
D('incur',{etymology:E('Incur comes from Latin incurrere, “to run into,” formed from in- and currere, “to run.” It means bringing an unpleasant consequence upon oneself, suffering a loss or penalty, or causing another person’s anger.','incur'),contexts:[C('incur.s1','项目管理','The company may incur additional costs if it delays ordering the custom parts until after production begins.','如果公司等到生产开始后才订购定制零件，可能会承担额外费用。','The company may incur additional costs / if it delays ordering / the custom parts / until after production begins.','incur 在此表示招致或承担不利后果、费用。','延迟订购可能导致额外支出。')],mistakes:[M('The company incurred extra costs by avoiding all expenses and paying nothing for the parts.','The company avoided incurring extra costs by ordering the parts early.','没有支出与承担额外费用相反。')],quiz:[Q('incur',1,1,'To incur a cost is to?','become responsible for it','avoid paying it entirely','earn it as income','become responsible for it','incur 可表示招致或承担费用。'),Q('incur',2,2,'To incur a penalty is to?','suffer or receive that penalty','escape all consequences','award it to someone else','suffer or receive that penalty','s2 表示遭受损失或惩罚。'),Q('incur',3,3,'A rude remark may incur someone’s?','anger','income','immunity','anger','s3 指招致他人的愤怒。'),Q('incur',4,1,'Which phrase is natural?','incur a financial loss','incur a birthday cake','incur the door open','incur a financial loss','incur a loss 是自然搭配。')]});
D('incursion',{etymology:E('Incursion comes from Latin incursio, from incurrere, “to run into or attack.” It means a sudden entry into foreign territory or an attack across a boundary.','incursion'),contexts:[C('incursion.s1','历史报道','The chronicle records an incursion across the border that forced nearby villages to evacuate.','编年史记载了一次越境突袭，迫使附近村庄撤离。','The chronicle records an incursion across the border / that forced nearby villages / to evacuate.','incursion 指突然进入外国领土或越境袭击。','突袭越境后，附近居民被迫撤离。')],mistakes:[M('The report called a routine visit arranged with the border officials an incursion.','The report called the sudden unauthorized crossing and attack an incursion.','经安排并获准的例行访问不是突然入侵。')],quiz:[Q('incursion',1,1,'An incursion is?','a sudden entry or attack into foreign territory','a routine local meeting','an annual increase in income','a sudden entry or attack into foreign territory','incursion 指突袭或突然进入他国领土。'),Q('incursion',2,1,'Which event is an incursion?','an armed group unexpectedly crosses a border','a delegation enters with permission for a meeting','a traveler checks into a hotel','an armed group unexpectedly crosses a border','未经许可的突袭越境符合 incursion。'),Q('incursion',3,1,'Incursion is related to the idea of?','running into or attacking','reading clearly','welcoming guests','running into or attacking','词源与冲入或攻击有关。','word-formation'),Q('incursion',4,1,'A historical account may describe an incursion as?','a sudden hostile crossing','a peaceful planned visit','a lawfully registered company','a sudden hostile crossing','突然敌对越境属于入侵事件。')]});
D('indebted',{etymology:E('Indebted comes from in-debt, from debt, ultimately Latin debitum, “something owed.” It means owing money or feeling very grateful to someone for help.','indebted'),contexts:[C('indebted.s1','感谢信','The researcher said she was indebted to her mentor for patient guidance during the difficult project.','研究人员说，在困难项目期间，她非常感激导师给予的耐心指导。','The researcher said / she was indebted to her mentor / for patient guidance / during the difficult project.','indebted 在此表示因得到帮助而深深感激某人。','耐心指导使研究人员对导师心怀感激。')],mistakes:[M('The researcher said she was indebted to her mentor but meant that the mentor owed her money.','The researcher said she was grateful to her mentor for the help.','感激某人是 grateful 义，不是说对方欠自己钱。')],quiz:[Q('indebted',1,1,'To feel indebted to a helper is to feel?','very grateful to them','angry that they helped','unable to read their note','very grateful to them','indebted 可比喻表示感激。'),Q('indebted',2,2,'A person indebted to a bank?','owes money to it','has paid every loan in full','is immune from tax','owes money to it','s2 指欠某人钱。'),Q('indebted',3,1,'Which sentence uses indebted to mean grateful?','I am indebted to you for your advice.','The bank is indebted to me for a loan I borrowed.','I indebted the report yesterday.','I am indebted to you for your advice.','for your advice 表示因帮助而感激。'),Q('indebted',4,1,'Indebted is related to the noun?','debt','incident','income','debt','indebted 与 debt（债务）相关。','word-formation')]});
D('indecent',{etymology:E('Indecent combines the negative prefix in- with decent, from Latin decens, “proper or becoming.” It describes behavior or material that is shocking, rude, or regarded as improper.','indecent'),contexts:[C('indecent.s1','公共场所','The theater posted a warning that the performance contained indecent language and might not be suitable for young children.','剧院张贴提示，说明演出含有不雅语言，可能不适合年幼儿童观看。','The theater posted a warning / that the performance contained indecent language / and might not be suitable / for young children.','indecent 表示令人震惊、粗鲁或不合礼仪的。','提示说明演出中有不适合儿童的粗俗语言。')],mistakes:[M('The review called the courteous greeting indecent even though it contained no rude or improper content.','The review called the rude, offensive remark indecent.','礼貌问候不符合粗俗或不雅的含义。')],quiz:[Q('indecent',1,1,'Indecent language is?','rude or shocking','polite and respectful','impossible to read','rude or shocking','indecent 可表示粗俗、不雅的。'),Q('indecent',2,1,'Which behavior may be called indecent?','a public act widely regarded as improper','a courteous thank-you note','a quiet library visit','a public act widely regarded as improper','被广泛认为不合礼仪的行为可称 indecent。'),Q('indecent',3,1,'Indecent is the opposite of?','decent','indefinite','indelible','decent','decent 表示得体，与 indecent 相反。'),Q('indecent',4,1,'The prefix in- contributes the meaning?','not','before','together','not','in- 是否定前缀。','word-formation')]});
D('indecipherable',{etymology:E('Indecipherable is formed from the negative prefix in-, decipher, and -able. It means impossible to read, understand, or decode.','indecipherable'),contexts:[C('indecipherable.s1','档案研究','The ink had run across the old letter, leaving several names indecipherable even under magnification.','墨水在旧信上洇开，即使用放大镜也有几个名字无法辨认。','The ink had run across the old letter / leaving several names indecipherable / even under magnification.','indecipherable 表示无法读出、理解或解码的。','放大后仍无法辨认的名字难以解读。')],mistakes:[M('The handwriting was indecipherable even though every word was printed clearly in large type.','The handwriting was legible because every word was clear in large type.','字迹清晰且字体很大，不符合无法辨认。')],quiz:[Q('indecipherable',1,1,'An indecipherable note is?','impossible to read or decode','written in a familiar clear hand','very rude','impossible to read or decode','indecipherable 表示无法辨认或解码的。'),Q('indecipherable',2,1,'Which message is indecipherable?','one with smeared symbols that cannot be decoded','one printed clearly in large letters','one translated into a known language','one with smeared symbols that cannot be decoded','符号被洇开且无法解码的内容难以辨认。'),Q('indecipherable',3,1,'Indecipherable is closest to?','unreadable','independent','indefatigable','unreadable','unreadable 与 indecipherable 接近。'),Q('indecipherable',4,1,'The ending -able usually means?','able to be','without','one who does','able to be','-able 表示能够被……。','word-formation')]});
D('indecision',{etymology:E('Indecision is formed from the negative prefix in- and decision. It means inability to make a choice.','indecision'),contexts:[C('indecision.s1','购物选择','After comparing the two repair plans for an hour, Sam’s indecision kept him from choosing either one.','比较两种维修方案一个小时后，萨姆仍犹豫不决，无法选定其中任何一种。','After comparing the two repair plans for an hour / Sam’s indecision kept him / from choosing / either one.','indecision 指无法作出选择的状态。','迟迟不能决定采用哪种方案体现 indecision。')],mistakes:[M('Sam showed indecision by choosing one plan immediately and never reconsidering it.','Sam showed decisiveness by choosing one plan immediately.','立即作出明确选择体现果断而不是犹豫不决。')],quiz:[Q('indecision',1,1,'Indecision is?','inability to make a choice','a final confident decision','freedom from control','inability to make a choice','indecision 指难以作出选择。'),Q('indecision',2,1,'Which person shows indecision?','someone who cannot choose between two plans','someone who selects a plan immediately','someone who follows a settled schedule','someone who cannot choose between two plans','无法在两个方案间选择体现犹豫。'),Q('indecision',3,1,'Indecision is the opposite of?','decisiveness','indecency','independence','decisiveness','果断与 indecision 相反。'),Q('indecision',4,1,'Indecision may delay?','making a choice','reading a clear sign','receiving income','making a choice','犹豫不决会拖延决定。')]});
D('indeed',{etymology:E('Indeed is formed from in and deed, historically “in fact or in truth.” It can emphasize a statement, confirm agreement, introduce a surprising fact, or strengthen very.','indeed'),contexts:[C('indeed.s3','科学报道','The early estimate was high; indeed, the final count was almost twice as large.','早期估算已经很高；事实上，最终数字几乎是它的两倍。','The early estimate was high / indeed / the final count was almost twice as large.','indeed 在此引出进一步且令人惊讶的事实。','最终数据比原估算还高，补充强化前文。')],mistakes:[M('The estimate was high; indeed, the final count was much lower and contradicted the claim.','The estimate was high; indeed, the final count was even higher.','若后文明显更低，就不能用 indeed 强化前文的高估说法。')],quiz:[Q('indeed',1,1,'At the end of “The result was surprising indeed,” indeed?','emphasizes that it really was surprising','denies that it was surprising','asks how it happened','emphasizes that it really was surprising','s1 用 indeed 强调陈述的真实性。'),Q('indeed',2,2,'“Yes, indeed” is used to?','confirm or agree','express indecision','describe a legal contract','confirm or agree','s2 表示确认或赞同。'),Q('indeed',3,3,'“It was difficult; indeed, it was nearly impossible” uses indeed to?','add a surprising or strengthening fact','introduce a new speaker','show a physical indentation','add a surprising or strengthening fact','s3 用于补充强化且令人意外的信息。'),Q('indeed',4,4,'“Very indeed useful” uses indeed to?','strengthen the word very','make a statement indefinite','refer to a country','strengthen the word very','s4 可放在 very 后加强语气。','grammar')]});
D('indefatigable',{etymology:E('Indefatigable comes from Latin indefatigabilis, “not able to be wearied,” formed from in- and defatigare, “to tire out.” It describes someone able to work for a long time without tiring.','indefatigable'),contexts:[C('indefatigable.s1','志愿服务','The indefatigable volunteers kept sorting donations throughout the day and returned the next morning to finish the work.','这些不知疲倦的志愿者整天持续整理捐赠物，第二天早晨又回来完成工作。','The indefatigable volunteers kept sorting donations / throughout the day / and returned the next morning / to finish the work.','indefatigable 形容能够长时间工作而不易疲倦的。','志愿者持续工作并次日再来，体现持久精力。')],mistakes:[M('The volunteers were called indefatigable because they stopped after five minutes from exhaustion.','The volunteers were called indefatigable because they worked steadily for long periods.','很快因疲惫停工不符合不知疲倦的特征。')],quiz:[Q('indefatigable',1,1,'An indefatigable worker?','can keep working for a long time without tiring','stops after a few minutes','avoids all activity','can keep working for a long time without tiring','indefatigable 表示不知疲倦的。'),Q('indefatigable',2,1,'Which volunteer is indefatigable?','one who continues steadily through a long day','one who quits immediately from fatigue','one who never begins the task','one who continues steadily through a long day','能长时间持续工作体现不知疲倦。'),Q('indefatigable',3,1,'Indefatigable is closest to?','tireless','indecisive','inconspicuous','tireless','tireless 与 indefatigable 意思相近。'),Q('indefatigable',4,1,'The prefix in- helps express?','not','again','under','not','in- 是否定前缀。','word-formation')]});
D('indefinite',{etymology:E('Indefinite comes from Latin indefinitus, “not defined,” formed from in- and definitus. It can mean lasting for an unspecified time, not clear or exact, or grammatically referring to no particular person or thing.','indefinite'),contexts:[C('indefinite.s1','政策通知','The museum closed its east wing for an indefinite period while engineers investigated the damaged roof.','工程师检查受损屋顶期间，博物馆东翼无限期关闭。','The museum closed its east wing / for an indefinite period / while engineers investigated / the damaged roof.','indefinite 在此表示持续时间尚未确定的。','通知没有给出重新开放日期。')],mistakes:[M('The wing was closed for an indefinite period, and the notice gave an exact reopening date of 10 a.m. tomorrow.','The wing was closed until further notice because no reopening date had been set.','已有确切日期就不是时间未定。')],quiz:[Q('indefinite',1,1,'An indefinite closure lasts?','for an unspecified length of time','for exactly one hour','until a named date only','for an unspecified length of time','indefinite 可表示持续时间未定。'),Q('indefinite',2,2,'An indefinite answer is?','not clear or exact','very precise','a physical slope','not clear or exact','s2 表示含糊、不确切。'),Q('indefinite',3,3,'An indefinite article such as “a” does not identify?','a particular person or thing','a time period','a type of image','a particular person or thing','s3 是不定冠词或代词的语法义。'),Q('indefinite',4,1,'Which notice describes an indefinite delay?','No new date has been set.','The event starts at exactly 3 p.m.','The delay will last ten minutes.','No new date has been set.','没有新日期表示延误时间未定。')]});
D('indefinitely',{etymology:E('Indefinitely is the adverb formed from indefinite plus -ly. It means for an unlimited or unspecified length of time, or in a way that is not clearly defined.','indefinitely'),contexts:[C('indefinitely.s1','设施维护','The footbridge will remain closed indefinitely until inspectors confirm that its supports are safe.','这座人行桥将无限期关闭，直到检查员确认支撑结构安全。','The footbridge will remain closed indefinitely / until inspectors confirm / that its supports / are safe.','indefinitely 在此表示持续时间没有确定期限。','桥梁关闭时间取决于安全检查，没有预定日期。')],mistakes:[M('The bridge will be closed indefinitely until 2 p.m. today, a precise and fixed closing period.','The bridge will be closed for a fixed period ending at 2 p.m. today.','明确到当天两点的期限不是 indefinitely。')],quiz:[Q('indefinitely',1,1,'To postpone indefinitely is to postpone?','for no specified end date','for exactly one day','until a date already announced','for no specified end date','indefinitely 表示期限未定或无限期。'),Q('indefinitely',2,2,'To describe something indefinitely is to describe it?','without clear definition','with exact boundaries','in alphabetical order','without clear definition','s2 表示定义不清楚地。'),Q('indefinitely',3,1,'Which sentence uses indefinitely correctly?','The service was suspended indefinitely pending repairs.','The service indefinitely at noon yesterday.','Indefinitely is a machine for eggs.','The service was suspended indefinitely pending repairs.','维修完成前无限期暂停服务。'),Q('indefinitely',4,1,'Indefinitely is formed from?','indefinite plus -ly','indelible plus -ness','indeed plus -ful','indefinite plus -ly','indefinitely 由 indefinite 加 -ly 构成。','word-formation')]});
D('indelible',{etymology:E('Indelible comes from Latin indelebilis, “not able to be destroyed,” formed from in- and delere, “to erase.” It describes a mark or memory that cannot be erased.','indelible'),contexts:[C('indelible.s1','个人回忆','The first visit to the mountain left an indelible memory of the sunrise above the clouds.','第一次登山留下了难以磨灭的记忆：云层之上升起的日出。','The first visit to the mountain left an indelible memory / of the sunrise / above the clouds.','indelible 在此表示无法抹去、难以忘怀的。','多年后仍清晰记得那次日出。')],mistakes:[M('The ink made an indelible mark that disappeared as soon as the paper was touched with water.','The ink made a permanent mark that could not be erased easily.','一碰水就消失的痕迹不是 indelible。')],quiz:[Q('indelible',1,1,'An indelible mark?','cannot be erased','disappears immediately','is hard to see because it is small','cannot be erased','indelible 表示无法擦除的。'),Q('indelible',2,1,'An indelible memory is?','one that remains vivid and cannot be forgotten','one forgotten immediately','one that has no emotional meaning','one that remains vivid and cannot be forgotten','难以忘怀的记忆会长期留存。'),Q('indelible',3,1,'Indelible is the opposite of?','erasable','independent','indecent','erasable','erasable 表示可擦除，与 indelible 相反。'),Q('indelible',4,1,'The Latin root delere meant?','to erase or destroy','to receive income','to bend or lean','to erase or destroy','delere 意为擦除或毁掉。','word-formation')]});
D('indemnification',{etymology:E('Indemnification is formed from indemnify plus -cation and is related to Latin indemnis, “unharmed.” It means payment or security provided to cover a loss or legal liability.','indemnification'),contexts:[C('indemnification.s1','合同条款','The agreement provides indemnification for documented repair costs if the equipment is damaged during delivery.','协议规定，如果设备在运输中损坏，将对有凭证的维修费用予以赔偿。','The agreement provides indemnification / for documented repair costs / if the equipment is damaged / during delivery.','indemnification 指用于弥补损失或法律责任的赔偿或保障。','合同明确运输损坏时的维修费用补偿。')],mistakes:[M('The contract offered indemnification by requiring the damaged party to pay the other side for every loss.','The contract offered indemnification by covering eligible losses or liabilities.','要求受损方反向承担对方损失不是赔偿保障。')],quiz:[Q('indemnification',1,1,'Indemnification provides?','payment or security to cover a loss or liability','a punishment for making a claim','a guarantee that no loss occurred','payment or security to cover a loss or liability','indemnification 指赔偿或损失保障。'),Q('indemnification',2,1,'A contract may provide indemnification for?','documented repair costs after covered damage','ordinary groceries unrelated to the agreement','a person’s reading ability','documented repair costs after covered damage','合同可规定对符合条件的维修费用给予补偿。'),Q('indemnification',3,1,'Indemnification is related to which verb?','indemnify','incinerate','inculcate','indemnify','indemnification 由 indemnify 派生。','word-formation'),Q('indemnification',4,1,'Which item is an indemnification provision?','a clause covering specified losses','a note describing a sunset','a list of book topics','a clause covering specified losses','合同中约定承担特定损失的条款属于 indemnification。')]});
D('indemnify',{etymology:E('Indemnify comes from Medieval Latin indemnis, “unharmed,” with the verb-forming suffix -fy. It means compensating someone for a loss or protecting them against a future loss.','indemnify'),contexts:[C('indemnify.s1','服务协议','The supplier agreed to indemnify the client for direct losses caused by a verified defect in the delivered equipment.','供应商同意对交付设备中经核实缺陷造成的直接损失向客户作出赔偿。','The supplier agreed to indemnify the client / for direct losses / caused by a verified defect / in the delivered equipment.','indemnify 表示补偿损失或为某人提供损失保障。','协议承诺对特定缺陷造成的损失予以补偿。')],mistakes:[M('The supplier indemnified the client by refusing all responsibility and requiring the client to cover the verified loss.','The supplier agreed to indemnify the client by covering the verified loss.','拒绝承担责任并让客户自付不构成赔偿。')],quiz:[Q('indemnify',1,1,'To indemnify a client is to?','compensate or protect them against a loss','charge them for an unrelated service','exclude them from a meeting','compensate or protect them against a loss','indemnify 表示赔偿或提供保障。'),Q('indemnify',2,1,'Which promise indemnifies a buyer?','covering specified losses from a defective product','denying all claims regardless of evidence','offering a discount on unrelated travel','covering specified losses from a defective product','对缺陷造成的特定损失提供补偿。'),Q('indemnify',3,1,'Indemnify is the verb related to the noun?','indemnification','indecision','indulgence','indemnification','indemnification 是相关名词。','word-formation'),Q('indemnify',4,1,'A company may indemnify another party against?','a defined future liability','a rise in temperature','a lack of imagination','a defined future liability','indemnify 可表示保护对方免受特定法律责任。')]});
D('indemnity',{etymology:E('Indemnity comes through French from Latin indemnis, “unharmed.” It can mean money paid to cover a loss, damage, or injury, or protection from legal responsibility.','indemnity'),contexts:[C('indemnity.s2','法律文件','The contract grants indemnity to the volunteer organization against certain claims arising from approved activities.','合同规定，志愿者组织可就经批准活动引发的某些索赔获得法律责任保障。','The contract grants indemnity to the volunteer organization / against certain claims / arising from approved activities.','indemnity 在此指免受某些法律责任的保障。','合同为组织提供特定范围的责任保护。')],mistakes:[M('The contract’s indemnity required the protected organization to pay every claim itself without any coverage.','The contract’s indemnity protected the organization against specified legal claims.','没有任何保障的条款不构成 indemnity。')],quiz:[Q('indemnity',1,1,'An indemnity payment covers?','loss, damage, or injury','ordinary wages only','a person’s inability to choose','loss, damage, or injury','indemnity 可指弥补损失的款项。'),Q('indemnity',2,2,'Legal indemnity may provide?','protection against being held responsible','a guaranteed win in every dispute','freedom from all laws everywhere','protection against being held responsible','s2 指法律责任保障，不意味着免于一切法律。'),Q('indemnity',3,1,'Which phrase is natural?','receive indemnity for a covered loss','indemnity a book alphabetically','indemnity the wall with a line','receive indemnity for a covered loss','因约定损失获得赔偿是自然搭配。'),Q('indemnity',4,1,'Indemnity is closely related to?','indemnification','incidence','indecency','indemnification','indemnity 和 indemnification 都与赔偿保障相关。','word-formation')]});
D('indent',{etymology:E('Indent comes from Middle English endenten, “to notch,” from a Latin root meaning “tooth.” It can mean a space set in from an edge or a notch, and as a verb to start a line farther in or cut a jagged edge.','indent'),contexts:[C('indent.s2','文档排版','The editor asked the writer to indent the first line of each paragraph to make the sections easier to distinguish.','编辑让作者把每段首行缩进，以便更容易区分各个段落。','The editor asked the writer / to indent the first line / of each paragraph / to make the sections easier to distinguish.','indent 在此作动词，表示将一行文字向内缩进。','首行比段落其他部分更靠右。')],mistakes:[M('The editor asked the writer to indent the first line by moving it farther left beyond the page edge.','The editor asked the writer to indent the first line by moving it inward from the margin.','缩进是向内移动，不是越过页面边缘向外移。')],quiz:[Q('indent',1,1,'An indent in a paragraph is?','a space set in from the edge','a word printed in bold','a list of dates','a space set in from the edge','indent 可指从边缘缩进去的空白。'),Q('indent',2,2,'To indent a line is to?','start it farther in from the margin','erase it completely','make it larger in size','start it farther in from the margin','s2 作动词表示行首缩进。'),Q('indent',3,1,'An indented coastline has?','notches or inlets along its edge','a perfectly straight edge','no connection to land','notches or inlets along its edge','indent 也可指在边缘切出缺口。'),Q('indent',4,1,'Which instruction uses indent correctly?','Indent the first line of each paragraph.','Indent means to read a sentence aloud.','Indent the page by moving text outside the margin.','Indent the first line of each paragraph.','每段首行缩进是常见排版要求。')]});
D('indented',{etymology:E('Indented is the past participle of indent and an adjective. It describes text set farther in from a margin or a coastline or edge cut into notches.','indented'),contexts:[C('indented.s1','写作格式','The indented quotation begins several spaces to the right of the main paragraph margin.','这段缩进引文的起始位置比正文段落边缘向右移了几个空格。','The indented quotation begins / several spaces to the right / of the main paragraph / margin.','indented 在此形容文字从页边向内移入的。','引文起点比正文边缘靠右。')],mistakes:[M('The quotation was indented because its first line began outside the page to the left of the margin.','The quotation was indented because its first line began farther in from the margin.','向页外左侧移动不是缩进。')],quiz:[Q('indented',1,1,'Indented text begins?','farther in from the margin','outside the page','at the bottom of every page','farther in from the margin','indented 表示向内缩进的。'),Q('indented',2,2,'An indented coastline is?','cut into notches','perfectly straight and smooth','printed in bold','cut into notches','s2 描述边缘有凹口的形状。'),Q('indented',3,1,'Which line is indented?','one beginning farther right than the margin','one beginning beyond the left edge','one that is missing','one beginning farther right than the margin','比页边向右移的行是缩进行。'),Q('indented',4,1,'Indented is related to the verb?','indent','indemnify','indeed','indent','indented 是 indent 的分词形容词。','word-formation')]});
D('indenture',{etymology:E('Indenture comes from Middle English endenture, a written contract whose copies once had matching notched edges. It names a legal agreement, especially one historically binding an apprentice to a master, or the act of binding by a service contract.','indenture'),contexts:[C('indenture.s1','法律史课程','The archive preserves an indenture that records the terms under which a young apprentice trained with a master craftsman.','档案馆保存了一份契约，记录一名年轻学徒在工匠师傅处接受训练的条款。','The archive preserves an indenture / that records the terms / under which a young apprentice / trained with a master craftsman.','indenture 在此指一种法律契约，历史上常用于约束学徒服务。','契约记录师徒培训的条件。')],mistakes:[M('The archivist called a casual verbal invitation an indenture although it created no formal agreement or service obligation.','The archivist called the written apprenticeship contract an indenture.','没有正式约定或服务义务的邀请不构成契约。')],quiz:[Q('indenture',1,1,'An indenture is a?','formal legal agreement','casual greeting','type of household income','formal legal agreement','indenture 指正式契约。'),Q('indenture',2,2,'Historically, an apprentice might sign an indenture to?','agree to a period of service and training','buy a house outright','receive immunity from every law','agree to a period of service and training','s2 作动词可指以服务契约约束某人。'),Q('indenture',3,1,'Which document is an indenture?','a written apprenticeship contract','a restaurant menu','a postcard with no agreement','a written apprenticeship contract','学徒契约属于 indenture。'),Q('indenture',4,1,'Indenture is associated with a formal?','contract','weather report','illustration','contract','该词主要用于正式法律协议。')]});
D('independence',{etymology:E('Independence is formed from independent plus -ence and ultimately from depend, “to rely on.” It means freedom from control by another person, organization, or country.','independence'),contexts:[C('independence.s1','历史纪念','The country celebrates its independence each year to mark the end of colonial rule.','这个国家每年庆祝独立纪念日，以纪念殖民统治的结束。','The country celebrates its independence each year / to mark the end / of colonial rule.','independence 指不再受他方控制的自由状态。','结束殖民统治标志国家摆脱外部控制。')],mistakes:[M('The country celebrated its independence while remaining fully controlled by the same colonial government.','The country celebrated independence after ending colonial control.','仍完全受同一殖民政府控制就没有获得独立。')],quiz:[Q('independence',1,1,'Political independence means?','freedom from control by another power','being managed directly by another country','having no written constitution','freedom from control by another power','independence 指摆脱他方控制。'),Q('independence',2,1,'A country may celebrate independence after?','ending colonial rule','being placed under new foreign control','joining a regional library','ending colonial rule','结束殖民统治可成为独立的标志。'),Q('independence',3,1,'Independence is the noun related to?','independent','indefinite','indelible','independent','independence 由 independent 派生。','word-formation'),Q('independence',4,1,'Which phrase is natural?','a declaration of independence','an indecision of independence','an independence the paragraph','a declaration of independence','declaration of independence 是自然搭配。')]});
D('independent',{etymology:E('Independent combines the negative prefix in- with dependent, from Latin dependere, “to hang from or rely on.” It can mean not controlled by another, self-reliant, nonpartisan, uninfluenced by something, or a candidate outside a party.','independent'),contexts:[C('independent.s4','新闻调查','An independent review checked the laboratory results without relying on the company’s own summary.','一项独立审查在不依赖公司自有摘要的情况下检查了实验室结果。','An independent review checked the laboratory results / without relying on / the company’s own summary.','independent 在此表示不受相关方影响或不依赖其说法的。','审查独立核验原始结果，没有依赖公司的总结。')],mistakes:[M('The review was independent because it copied the company’s conclusions without checking any original evidence.','The review was independent because it checked the original results without relying on the company.','照抄公司结论且不核查证据，不能称为独立审查。')],quiz:[Q('independent',1,1,'An independent country is?','not controlled by another country','governed directly by a foreign power','unable to read','not controlled by another country','s1 指不受其他国家控制的。'),Q('independent',2,2,'An independent adult can?','look after themselves without help','never make a decision','be controlled by another person','look after themselves without help','s2 指能够独立照料自己。'),Q('independent',3,3,'An independent candidate is?','not belonging to a political party','the official party nominee','a person currently holding a foreign office','not belonging to a political party','s5 指不隶属政党的候选人。'),Q('independent',4,4,'An independent assessment is?','not connected with or influenced by the subject','copied from the subject’s own report','based only on a rumor','not connected with or influenced by the subject','s4 表示不受研究对象影响。')]});
D('independently',{etymology:E('Independently is the adverb formed from independent plus -ly. It means separately from other people or factors, or without relying on them.','independently'),contexts:[C('independently.s1','科学实验','The two laboratories analyzed the samples independently before comparing their results.','两家实验室先各自独立分析样本，然后再比较结果。','The two laboratories analyzed the samples independently / before comparing / their results.','independently 表示彼此分开、不依赖他人地。','两家实验室在比较前分别完成分析。')],mistakes:[M('The laboratories worked independently by sharing one unverified answer and copying it without testing samples.','The laboratories worked independently by analyzing their own samples separately.','照抄同一个未验证答案不属于独立分析。')],quiz:[Q('independently',1,1,'To work independently is to work?','separately from others','only under another person’s constant direction','without completing any task','separately from others','independently 表示独立地或分别地。'),Q('independently',2,1,'Which teams worked independently?','each team ran its own analysis before sharing results','both teams copied one result without testing','one team directed every action of the other','each team ran its own analysis before sharing results','各自完成分析体现独立工作。'),Q('independently',3,1,'Independently is the adverb from?','independent','indeterminate','indecent','independent','independently 由 independent 加 -ly 构成。','word-formation'),Q('independently',4,1,'If two reports are prepared independently, they are?','made separately rather than copied from each other','identical because one copied the other','unreadable','made separately rather than copied from each other','独立撰写意味着没有互相照抄。')]});
D('indeterminate',{etymology:E('Indeterminate comes from Latin indeterminatus, “not limited or defined,” formed from in- and determinare, “to set a boundary.” It means not precisely determined and therefore vague or unsettled.','indeterminate'),contexts:[C('indeterminate.s1','科学测量','Because the sample was damaged, its exact age remained indeterminate despite repeated tests.','由于样本受损，尽管进行了多次检测，其确切年代仍无法确定。','Because the sample was damaged / its exact age remained indeterminate / despite repeated tests.','indeterminate 表示无法精确确定、仍然模糊或未定的。','多次检测仍无法确定确切年代。')],mistakes:[M('The sample’s age was called indeterminate even though several independent tests established it as exactly 40 years old.','The sample’s age was determined to be 40 years old by repeated tests.','多次测试得出确切年龄时，不再是未确定的。')],quiz:[Q('indeterminate',1,1,'An indeterminate result is?','not precisely determined','exact and fully settled','impossible to erase','not precisely determined','indeterminate 表示不确定或未定的。'),Q('indeterminate',2,1,'Which quantity is indeterminate?','a value that remains vague after testing','a value measured exactly to the unit','a date printed on a ticket','a value that remains vague after testing','测试后仍模糊不清的数值是未确定的。'),Q('indeterminate',3,1,'Indeterminate is closest to?','unsettled','indelible','incorruptible','unsettled','unsettled 与 indeterminate 意义接近。'),Q('indeterminate',4,1,'The prefix in- contributes the meaning?','not','very','between','not','in- 是否定前缀。','word-formation')]});
D('index',{etymology:E('Index comes from Latin index, “indicator or informer.” It can mean a book’s alphabetical list, a number measuring changes in values, a sign or measure, the act of creating a book index, or linking payments to a price index.','index'),contexts:[C('index.s5','劳资协议','The agreement will index wages to the cost-of-living measure so that pay can adjust as prices change.','协议将工资与生活成本指标挂钩，以便薪酬能随价格变化调整。','The agreement will index wages / to the cost-of-living measure / so that pay can adjust / as prices change.','index 在此作动词，表示把工资与价格指数挂钩。','工资调整依据生活成本指标变化。')],mistakes:[M('The agreement indexed wages to prices by fixing them permanently and forbidding any adjustment when prices changed.','The agreement linked wage adjustments to changes in the price index.','禁止调整不能称为与价格指数挂钩调整。')],quiz:[Q('index',1,1,'An index at the back of a book is?','an alphabetical list showing where topics appear','a chapter containing the whole story','a measure of a person’s height','an alphabetical list showing where topics appear','index 可指书后主题索引。'),Q('index',2,2,'A price index is?','a number showing how prices or values change','an alphabetical list of book topics','a written legal agreement','a number showing how prices or values change','s2 指衡量价格或价值变化的数字。'),Q('index',3,3,'A sign can be an index of?','something it indicates or measures','a person’s inability to decide','a line of text moved inward','something it indicates or measures','s3 可指某事物的迹象或衡量指标。'),Q('index',4,4,'To index a book is to?','make an alphabetical list of its topics','write the book’s final chapter','link a salary to prices','make an alphabetical list of its topics','index 作动词可指为书编制索引。')]});
D('Indian',{etymology:E('Indian is formed from India with the suffix -an, meaning “from or relating to.” It can describe a person from India or something belonging to or connected with India.','Indian'),contexts:[C('Indian.s1','国际交流','The Indian student joined the exchange program after completing her studies in Mumbai.','这名印度学生在孟买完成学业后参加了交流项目。','The Indian student joined the exchange program / after completing her studies / in Mumbai.','Indian 在此作名词性形容词，指来自印度的人。','人物来自印度并参加国际交流。')],mistakes:[M('The article called a student from India Indian but stated that the word meant a person from Iceland.','The article called the student from India Indian.','Indian 指与印度有关，不是来自冰岛。')],quiz:[Q('Indian',1,1,'An Indian is a person from?','India','Indonesia','Ireland','India','Indian 可指来自印度的人。'),Q('Indian',2,2,'Indian cuisine is cuisine?','connected with India','from Iceland','unrelated to a country','connected with India','s2 表示与印度相关的。'),Q('Indian',3,1,'Which phrase uses Indian as an adjective?','Indian literature','a person who is Indian','the India is a noun','Indian literature','Indian literature 指印度文学。'),Q('Indian',4,1,'Indian is formed from India plus?','-an','-less','-hood','-an','-an 可构成表示来自某地或与某地相关的词。','word-formation')]});

})();
